            const _dk = ['7f3c9e21', 'b84d0a56', 'c2e18f73', '9a6d4b08'];
            const _ks = [0x5a, 0x3c, 0x7e, 0x1f];

            function _digestHex() {
                return _hk.map(s => s.split('').reverse().join('')).reverse().join('');
            }

            function sha256Fallback(str) {
                function rightRotate(v, a) { return (v >>> a) | (v << (32 - a)); }
                const maxWord = Math.pow(2, 32);
                let result = '';
                const words = [];
                const asciiBitLength = str.length * 8;
                let hash = sha256Fallback.h = sha256Fallback.h || [];
                const k = sha256Fallback.k = sha256Fallback.k || [];
                let primeCounter = k.length;
                const isComposite = {};
                for (let candidate = 2; primeCounter < 64; candidate++) {
                    if (!isComposite[candidate]) {
                        for (let i = 0; i < 313; i += candidate) isComposite[i] = candidate;
                        hash[primeCounter] = (Math.pow(candidate, 0.5) * maxWord) | 0;
                        k[primeCounter++] = (Math.pow(candidate, 1 / 3) * maxWord) | 0;
                    }
                }
                let ascii = str + '\x80';
                while (ascii.length % 64 - 56) ascii += '\x00';
                for (let i = 0; i < ascii.length; i++) {
                    const j = ascii.charCodeAt(i);
                    if (j >> 8) return '';
                    words[i >> 2] |= j << ((3 - i) % 4) * 8;
                }
                words[words.length] = (asciiBitLength / maxWord) | 0;
                words[words.length] = asciiBitLength;
                for (let j = 0; j < words.length;) {
                    const w = words.slice(j, j += 16);
                    const oldHash = hash.slice(0, 8);
                    hash = hash.slice(0, 8);
                    for (let i = 0; i < 64; i++) {
                        const w15 = w[i - 15], w2 = w[i - 2];
                        const a = hash[0], e = hash[4];
                        const temp1 = hash[7]
                            + (rightRotate(e, 6) ^ rightRotate(e, 11) ^ rightRotate(e, 25))
                            + ((e & hash[5]) ^ ((~e) & hash[6]))
                            + k[i]
                            + (w[i] = (i < 16) ? w[i] : (w[i - 16] + (rightRotate(w15, 7) ^ rightRotate(w15, 18) ^ (w15 >>> 3)) + w[i - 7] + (rightRotate(w2, 17) ^ rightRotate(w2, 19) ^ (w2 >>> 10))) | 0);
                        const temp2 = (rightRotate(a, 2) ^ rightRotate(a, 13) ^ rightRotate(a, 22)) + ((a & hash[1]) ^ (a & hash[2]) ^ (hash[1] & hash[2]));
                        hash = [(temp1 + temp2) | 0].concat(hash);
                        hash[4] = (hash[4] + temp1) | 0;
                    }
                    for (let i = 0; i < 8; i++) hash[i] = (hash[i] + oldHash[i]) | 0;
                }
                for (let i = 0; i < 8; i++) {
                    for (let j = 3; j + 1; j--) {
                        const b = (hash[i] >> (j * 8)) & 255;
                        result += ((b < 16) ? 0 : '') + b.toString(16);
                    }
                }
                return result;
            }

            function sha256Hex(str) {
                if (window.crypto && window.crypto.subtle && window.isSecureContext) {
                    return window.crypto.subtle.digest('SHA-256', new TextEncoder().encode(str))
                        .then((buf) => Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join(''))
                        .catch(() => sha256Fallback(str));
                }
                return Promise.resolve(sha256Fallback(str));
            }

            let _admFails = 0;
            let _admLockUntil = 0;

            async function verifyAdminPassword(input) {
                if (Date.now() < _admLockUntil) return false;
                const hex = await sha256Hex('KravenGame::' + input + '::v2026');
                if (hex === _digestHex()) { _admFails = 0; return true; }
                _admFails++;
                if (_admFails >= 5) { _admLockUntil = Date.now() + 30000; _admFails = 0; }
                return false;
            }

            function openAdminLogin() {
                const modal = document.getElementById('admin-login-modal');
                const input = document.getElementById('admin-login-pass');
                document.getElementById('admin-login-error').textContent = '';
                input.value = '';
                modal.classList.add('open');
                setTimeout(() => input.focus(), 60);
            }
            function closeAdminLogin() {
                document.getElementById('admin-login-modal').classList.remove('open');
            }
            async function submitAdminLogin() {
                if (Date.now() < _admLockUntil) {
                    showToast('تلاش بیش از حد؛ لطفاً چند لحظه صبر کنید', 'error');
                    return;
                }
                const input = document.getElementById('admin-login-pass');
                const ok = await verifyAdminPassword(input.value);
                if (ok) {
                    closeAdminLogin();
                    isAdmin = true;
                    document.body.classList.add('admin-mode');
                    document.getElementById('admin-nav-link').style.display = 'flex';
                    showToast('ورود موفق به پنل مدیریت', 'success');
                    startAdminSessionTimer();
                    navigateTo('admin');
                } else {
                    document.getElementById('admin-login-error').textContent =
                        (Date.now() < _admLockUntil) ? 'تلاش بیش از حد؛ ۳۰ ثانیه صبر کنید' : 'رمز اشتباه است!';
                    input.value = '';
                    input.focus();
                }
            }
            window._closeAdminLogin = closeAdminLogin;
            window._submitAdminLogin = submitAdminLogin;

            let adminIdleTimer = null;
            function startAdminSessionTimer() {
                clearTimeout(adminIdleTimer);
                adminIdleTimer = setTimeout(() => {
                    if (!isAdmin) return;
                    isAdmin = false;
                    document.body.classList.remove('admin-mode');
                    document.getElementById('admin-nav-link').style.display = 'none';
                    showToast('به دلیل عدم فعالیت از پنل مدیریت خارج شدید', 'info');
                    if (currentPage === 'admin') navigateTo('home');
                }, 15 * 60 * 1000);
            }
            const DB_NAME = 'KravenGameDB';
            const DB_VERSION = 5;
            const STORES = {
                games: 'games', news: 'news', settings: 'settings', chatbot: 'chatbot',
                messages: 'messages', tutorials: 'tutorials', faq: 'faq', ratings: 'ratings', views: 'views',
                ads: 'ads', adSlots: 'adSlots',
                users: 'users', comments: 'comments', reviews: 'reviews', bookmarks: 'bookmarks',
                notifications: 'notifications', gameRequests: 'gameRequests', reports: 'reports',
                activityLogs: 'activityLogs', releases: 'releases', viewEvents: 'viewEvents'
            };
            let db = null;
            let isAdmin = false;

            let logoClickCount = 0;
            let logoClickTimer = null;
            let currentPage = 'home';
            let currentGameId = null;
            let currentNewsId = null;
            let likes = JSON.parse(localStorage.getItem('kraven_likes') || '{}');
            let userRatings = JSON.parse(localStorage.getItem('kraven_user_ratings') || '{}');
            let views = JSON.parse(localStorage.getItem('kraven_views') || '{}');
            let theme = parseInt(localStorage.getItem('kraven_theme') || '1');
            let featuredIndex = 0;
            let featuredTimer = null;
            let currentGalleryImages = [];
            let currentLightboxIndex = 0;
            let compareList = JSON.parse(localStorage.getItem('kraven_compare') || '[]');
            let deferredInstallPrompt = null;

            function openDB() {
                return new Promise((resolve, reject) => {
                    const request = indexedDB.open(DB_NAME, DB_VERSION);
                    request.onupgradeneeded = (e) => {
                        const d = e.target.result;
                        if (!d.objectStoreNames.contains(STORES.games)) d.createObjectStore(STORES.games, { keyPath: 'id' });
                        if (!d.objectStoreNames.contains(STORES.news)) d.createObjectStore(STORES.news, { keyPath: 'id' });
                        if (!d.objectStoreNames.contains(STORES.settings)) d.createObjectStore(STORES.settings, { keyPath: 'id' });
                        if (!d.objectStoreNames.contains(STORES.chatbot)) d.createObjectStore(STORES.chatbot, { keyPath: 'id' });
                        if (!d.objectStoreNames.contains(STORES.messages)) d.createObjectStore(STORES.messages, { keyPath: 'id', autoIncrement: true });
                        if (!d.objectStoreNames.contains(STORES.tutorials)) d.createObjectStore(STORES.tutorials, { keyPath: 'id' });
                        if (!d.objectStoreNames.contains(STORES.faq)) d.createObjectStore(STORES.faq, { keyPath: 'id' });
                        if (!d.objectStoreNames.contains(STORES.ratings)) d.createObjectStore(STORES.ratings, { keyPath: 'gameId' });
                        if (!d.objectStoreNames.contains(STORES.views)) d.createObjectStore(STORES.views, { keyPath: 'gameId' });
                        if (!d.objectStoreNames.contains(STORES.ads)) d.createObjectStore(STORES.ads, { keyPath: 'id' });
                        if (!d.objectStoreNames.contains(STORES.adSlots)) d.createObjectStore(STORES.adSlots, { keyPath: 'id' });
                        ['users','comments','reviews','bookmarks','notifications','gameRequests','reports','activityLogs','releases','viewEvents'].forEach(s => {
                            if (!d.objectStoreNames.contains(s)) d.createObjectStore(s, { keyPath: 'id' });
                        });
                    };
                    request.onsuccess = (e) => { db = e.target.result; resolve(db); };
                    request.onerror = (e) => reject(e.target.error);
                });
            }

            function dbAdd(store, data) {
                return new Promise((resolve, reject) => {
                    const tx = db.transaction(store, 'readwrite');
                    const req = tx.objectStore(store).add(data);
                    req.onsuccess = () => { if (store === STORES.games) invalidateGamesCache(); window.KRAVEN_CONTENT_SYNC?.schedule?.(); resolve(req.result); };
                    req.onerror = () => reject(req.error);
                });
            }

            function dbPut(store, data) {
                return new Promise((resolve, reject) => {
                    const tx = db.transaction(store, 'readwrite');
                    const req = tx.objectStore(store).put(data);
                    req.onsuccess = () => { if (store === STORES.games) invalidateGamesCache(); window.KRAVEN_CONTENT_SYNC?.schedule?.(); resolve(req.result); };
                    req.onerror = () => reject(req.error);
                });
            }

            function dbDelete(store, id) {
                return new Promise((resolve, reject) => {
                    const tx = db.transaction(store, 'readwrite');
                    const req = tx.objectStore(store).delete(id);
                    req.onsuccess = () => { if (store === STORES.games) invalidateGamesCache(); window.KRAVEN_CONTENT_SYNC?.schedule?.(); resolve(); };
                    req.onerror = () => reject(req.error);
                });
            }

            function dbGetAll(store) {
                return new Promise((resolve, reject) => {
                    const tx = db.transaction(store, 'readonly');
                    const req = tx.objectStore(store).getAll();
                    req.onsuccess = () => resolve(req.result || []);
                    req.onerror = () => reject(req.error);
                });
            }

            // تابع dbGet اصلاح‌شده
            function dbGet(store, id) {
                return new Promise((resolve, reject) => {
                    if (id === null || id === undefined) {
                        resolve(undefined);
                        return;
                    }
                    const tx = db.transaction(store, 'readonly');
                    const req = tx.objectStore(store).get(id);
                    req.onsuccess = () => resolve(req.result);
                    req.onerror = () => reject(req.error);
                });
            }

            function dbClear(store) {
                return new Promise((resolve, reject) => {
                    const tx = db.transaction(store, 'readwrite');
                    const req = tx.objectStore(store).clear();
                    req.onsuccess = () => resolve();
                    req.onerror = () => reject(req.error);
                });
            }

            function showToast(message, type = 'info', duration = 3000) {
                const container = document.getElementById('toast-container');
                const toast = document.createElement('div');
                toast.className = `toast ${type}`;
                toast.textContent = message;
                Object.assign(toast.style, {
                    background: 'rgba(20,20,20,0.85)', border: '1px solid rgba(255,255,255,0.25)', borderRadius: '25px',
                    padding: '14px 22px', color: 'var(--text-primary)', fontSize: '0.9rem',
                    boxShadow: '0 16px 64px rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center',
                    gap: '8px', animation: 'fadeIn 0.3s'
                });
                container.appendChild(toast);
                setTimeout(() => { toast.style.opacity = '0'; toast.style.transform = 'translateY(20px)'; setTimeout(() => toast.remove(), 300); }, duration);
            }

            function showConfirm(message, title = 'آیا مطمئن هستید؟', icon = '⚠️') {
                return new Promise((resolve) => {
                    const dialog = document.getElementById('confirm-dialog');
                    document.getElementById('confirm-icon').textContent = icon;
                    document.getElementById('confirm-title').textContent = title;
                    document.getElementById('confirm-message').textContent = message;
                    dialog.classList.add('open');
                    const yesBtn = document.getElementById('confirm-yes');
                    const noBtn = document.getElementById('confirm-no');
                    const cleanup = () => { dialog.classList.remove('open'); yesBtn.onclick = null; noBtn.onclick = null; };
                    yesBtn.onclick = () => { cleanup(); resolve(true); };
                    noBtn.onclick = () => { cleanup(); resolve(false); };
                });
            }

            function openSidebar() {
                document.getElementById('sidebar-menu').classList.add('open');
                document.getElementById('menu-overlay').classList.add('open');
            }

            function closeSidebar() {
                document.getElementById('sidebar-menu').classList.remove('open');
                document.getElementById('menu-overlay').classList.remove('open');
            }

            let isPopstateNavigation = false;

            function navigateTo(page) {
                if (page === 'admin' && !isAdmin) { showToast('دسترسی غیرمجاز!', 'error'); return; }
                if (page === 'game-detail' && !currentGameId) return;
                if (page === 'news-detail' && !currentNewsId) { page = 'news'; }
                if ((page === 'profile' || page === 'bookmarks' || page === 'requests') && !PLATFORM_USER()) {
                    showToast('برای دسترسی به این بخش ابتدا وارد شوید', 'warning');
                    openAuthModal();
                    return;
                }
                const fromPopstate = isPopstateNavigation;
                isPopstateNavigation = false;
                currentPage = page;
                document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
                const targetPage = document.getElementById(`page-${page}`);
                if (targetPage) targetPage.classList.add('active');
                document.querySelectorAll('.sidebar-nav a').forEach(a => a.classList.toggle('active', a.dataset.page === page));
                closeSidebar();
                window.scrollTo({ top: 0, behavior: 'smooth' });
                if (page === 'favorites') renderFavorites();
                if (page === 'news') renderNews();
                if (page === 'news-detail') renderNewsDetail(currentNewsId);
                if (page === 'admin') renderAdminPanel();
                if (page === 'faq') renderFAQ();
                if (page === 'tutorials') renderTutorials();
                if (page === 'compare') renderComparePage();
                if (page === 'home') { renderGames(); renderFeaturedSlider(); renderHomeExtras(); }
                if (page === 'game-detail') renderGameDetail(currentGameId);
                if (page === 'profile') renderProfilePage();
                if (page === 'bookmarks') renderBookmarksPage();
                if (page === 'requests') renderRequestsPage();
                if (page === 'calendar') renderCalendarPage();
                scheduleAdSync();
                // Lightweight navigation signal for enhancement layers.
                // Avoids expensive body-wide MutationObservers.
                try { window.dispatchEvent(new CustomEvent('kraven:navigate', { detail: { page } })); } catch (_) {}
                if (PAGE_TITLES[page] && page !== 'game-detail' && page !== 'news-detail') document.title = PAGE_TITLES[page];
                if (!fromPopstate) {
                    let newHash = '#/' + page;
                    if (page === 'game-detail' && currentGameId) newHash = '#/game-detail/' + currentGameId;
                    if (page === 'news-detail' && currentNewsId) newHash = '#/news-detail/' + currentNewsId;
                    if (location.hash !== newHash) history.pushState(null, '', newHash);
                }
            }

            const VALID_PAGES = ['home', 'game-detail', 'favorites', 'news', 'news-detail', 'about', 'contact', 'faq', 'tutorials', 'compare', 'admin', 'profile', 'bookmarks', 'requests', 'calendar'];

            function pageFromHash() {
                const parts = location.hash.replace(/^#\/?/, '').split('/').filter(Boolean);
                const page = parts[0] || 'home';
                if (page === 'game-detail' && parts[1]) currentGameId = parts[1];
                if (page === 'news-detail' && parts[1]) currentNewsId = parts[1];
                return VALID_PAGES.includes(page) ? page : 'home';
            }

            function initBrowserHistory() {
                window.addEventListener('popstate', () => {
                    isPopstateNavigation = true;
                    navigateTo(pageFromHash());
                });
                const initial = pageFromHash();
                const initialHash = (initial === 'game-detail' && currentGameId)
                    ? '#/game-detail/' + currentGameId
                    : '#/' + initial;
                history.replaceState(null, '', initialHash);
                history.pushState(null, '', initialHash);
                isPopstateNavigation = true;
                navigateTo(initial);
            }

            function applyTheme(t) {
                theme = t;
                document.body.dataset.theme = t;
                localStorage.setItem('kraven_theme', t);
                document.querySelectorAll('.theme-dot').forEach(d => d.classList.toggle('active', parseInt(d.dataset.theme) === t));
            }

            function initScrollProgress() {
                window.addEventListener('scroll', () => {
                    const scrollTop = window.scrollY;
                    const docHeight = document.documentElement.scrollHeight - window.innerHeight;
                    const progress = (scrollTop / docHeight) * 100;
                    document.getElementById('scroll-progress').style.width = progress + '%';
                    const scrollBtn = document.getElementById('scroll-top-btn');
                    if (scrollTop > 300) { scrollBtn.classList.add('visible'); } else { scrollBtn.classList.remove('visible'); }
                    const header = document.getElementById('main-header');
                    if (scrollTop > 50) { header.classList.add('scrolled'); } else { header.classList.remove('scrolled'); }
                });
            }

            function hideLoading() {
                setTimeout(() => {
                    document.getElementById('loading-screen').classList.add('hidden');
                    setTimeout(() => { document.getElementById('loading-screen').style.display = 'none'; }, 500);
                }, 800);
            }

            function toggleFullscreen() {
                if (!document.fullscreenElement) { document.documentElement.requestFullscreen().catch(() => {}); }
                else { document.exitFullscreen().catch(() => {}); }
            }

            function initLogoClick() {
                document.getElementById('logo').addEventListener('click', () => {
                    logoClickCount++;
                    clearTimeout(logoClickTimer);
                    logoClickTimer = setTimeout(() => { logoClickCount = 0; }, 1500);
                    if (logoClickCount >= 5) {
                        logoClickCount = 0;
                        if (!isAdmin) {
                            openAdminLogin();
                        } else {
                            showToast('شما قبلاً وارد شده‌اید', 'info');
                        }
                    }
                });
            }

            function initProtection() {
                document.addEventListener('contextmenu', (e) => { if (!isAdmin) { e.preventDefault(); showToast('کپی محتوا غیرمجاز است', 'warning'); } });
                document.addEventListener('copy', (e) => { if (!isAdmin) { e.preventDefault(); showToast('کپی محتوا غیرمجاز است', 'warning'); } });
                document.addEventListener('cut', (e) => { if (!isAdmin) { e.preventDefault(); showToast('کپی محتوا غیرمجاز است', 'warning'); } });
                document.addEventListener('selectstart', (e) => { if (!isAdmin) e.preventDefault(); });

                // Anti-screenshot / anti-print / anti-devtools layer
                const shield = document.getElementById('privacy-shield');
                let shieldTimer = null;
                const showShield = (ms) => {
                    shield.classList.add('show');
                    clearTimeout(shieldTimer);
                    if (ms) shieldTimer = setTimeout(() => shield.classList.remove('show'), ms);
                };
                const hideShield = () => { clearTimeout(shieldTimer); shield.classList.remove('show'); };

                document.addEventListener('keydown', (e) => {
                    if (isAdmin) return;
                    const k = (e.key || '').toLowerCase();
                    if (k === 'printscreen' || (e.ctrlKey && e.shiftKey && ['i','j','c','k'].includes(k)) || k === 'f12') {
                        e.preventDefault();
                        showShield(2200);
                        try { navigator.clipboard.writeText(' '); } catch (err) {}
                        showToast('گرفتن اسکرین‌شات مجاز نیست', 'warning');
                    }
                    if ((e.ctrlKey || e.metaKey) && ['p','s','u'].includes(k)) {
                        e.preventDefault();
                        showShield(2200);
                        showToast('این عملیات مجاز نیست', 'warning');
                    }
                });
                document.addEventListener('keyup', (e) => {
                    if (!isAdmin && (e.key || '').toLowerCase() === 'printscreen') {
                        try { navigator.clipboard.writeText(' '); } catch (err) {}
                    }
                });
                window.addEventListener('beforeprint', () => { if (!isAdmin) showShield(); });
                window.addEventListener('afterprint', hideShield);
                document.addEventListener('visibilitychange', () => {
                    if (isAdmin) return;
                    if (document.hidden) { showShield(); }
                    else { hideShield(); }
                });
                window.addEventListener('blur', () => { if (!isAdmin) showShield(); });
                window.addEventListener('focus', hideShield);
                // Deterrent: console warning on devtools open
                setInterval(() => {
                    if (isAdmin) return;
                    const devOpen = window.outerWidth - window.innerWidth > 220 || window.outerHeight - window.innerHeight > 260;
                    if (devOpen) showShield(2500);
                }, 8000);
            }

            function initKeyboardShortcuts() {
                document.addEventListener('keydown', (e) => {
                    if (e.key === '/' && document.activeElement.tagName !== 'INPUT' && document.activeElement.tagName !== 'TEXTAREA') {
                        e.preventDefault();
                        const searchInput = document.getElementById('search-input');
                        if (searchInput) { searchInput.focus(); navigateTo('home'); }
                    }
                    if (e.key === 'Escape') {
                        closeSidebar();
                        closeLightbox();
                        document.getElementById('theme-modal').classList.remove('open');
                        document.getElementById('chatbot-panel').classList.remove('open');
                    }
                });
                // Graceful fallback when a cover image fails to load.
                document.addEventListener('error', (e) => {
                    const img = e.target;
                    if (!img || img.tagName !== 'IMG' || img.dataset.fallbackApplied) return;
                    img.dataset.fallbackApplied = '1';
                    img.src = 'data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 320 180%22%3E%3Crect width=%22320%22 height=%22180%22 fill=%22%23222222%22/%3E%3Ctext x=%22160%22 y=%22105%22 font-size=%2248%22 text-anchor=%22middle%22 fill=%22%23707070%22%3E%F0%9F%8E%AE%3C/text%3E%3C/svg%3E';
                    img.style.objectFit = 'cover';
                }, true);
            }

            function initScrollReveal() {
                const observer = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) { entry.target.classList.add('visible'); observer.unobserve(entry.target); }
                    });
                }, { threshold: 0.1 });
                document.querySelectorAll('.reveal').forEach(el => observer.observe(el));
            }

            // Card tilt is handled by the delegated fx-tilt module at the end
            // of <body>; no per-card mousemove listener is needed here.

            // In-memory cache so the 200+ game records (with inline cover art)
            // are not re-fetched from IndexedDB on every render pass.
            let gamesCache = null;
            function invalidateGamesCache() { gamesCache = null; }

            async function getGames() {
                if (gamesCache) return gamesCache;
                gamesCache = await dbGetAll(STORES.games);
                return gamesCache;
            }
            async function getGameById(id) {
                if (gamesCache) return gamesCache.find(g => g.id === id) || await dbGet(STORES.games, id);
                return await dbGet(STORES.games, id);
            }
            function getGameRating(game) {
                if (game.userRatings && game.userRatings.length > 0) {
                    const sum = game.userRatings.reduce((a, b) => a + parseFloat(b), 0);
                    return (sum / game.userRatings.length).toFixed(1);
                }
                if (game.rating) return parseFloat(game.rating).toFixed(1);
                return '0.0';
            }
            function getGameRatingCount(game) { return game.userRatings ? game.userRatings.length : 0; }
            function getAllGenres(games) {
                const genres = new Set();
                games.forEach(g => { if (g.genre) genres.add(g.genre); });
                return Array.from(genres).sort();
            }
            function getGameBadge(game) {
                const rating = parseFloat(getGameRating(game));
                const likeCount = Math.max(Number(game.likes) || 0, likes[game.id] ? 1 : 0);
                const createdAt = new Date(game.createdAt || 0);
                const isNew = (Date.now() - createdAt.getTime()) / 86400000 <= 14;
                const updatedAt = game.updatedAt ? new Date(game.updatedAt) : null;
                if (rating >= 9) return '<span class="badge badge-top">🏆 برتر</span>';
                if (likeCount >= 10) return '<span class="badge badge-hot">🔥 داغ</span>';
                if (updatedAt && updatedAt > createdAt) return '<span class="badge badge-updated">♻️ به‌روزرسانی</span>';
                if (isNew) return '<span class="badge badge-new">⭐ جدید</span>';
                return '';
            }

            // ===== VGDL download link (shown on every game) =====
            const VGDL_URL = 'https://vgdl.ir';
            function vgdlBtn(large) {
                return `<a class="vgdl-btn${large ? ' large' : ''}" href="${VGDL_URL}" target="_blank" rel="noopener" onclick="event.stopPropagation();" title="دانلود از سایت VGDL">⬇️ دانلود از سایت VGDL</a>`;
            }
            function gameCardChips(game) {
                return `<div class="game-card-tags">
                    <span class="game-card-genre">${esc(game.genre || 'نامشخص')}</span>
                    ${game.year ? `<span class="game-card-chip">📅 ${esc(String(game.year))}</span>` : ''}
                    ${game.platform ? `<span class="game-card-chip">🖥️ ${esc(String(game.platform).split('/')[0].trim())}</span>` : ''}
                </div>`;
            }

            function buildFeaturedCard(game, index) {
                const isLiked = likes[game.id] ? 'liked' : '';
                const rating = getGameRating(game);
                const imageSrc = game.imageData || '';
                const badge = getGameBadge(game);
                const titleSafe = esc(game.title || 'بدون عنوان');
                return `
                            <div class="game-card card-visible" style="animation-delay:${index * 0.06}s;position:relative;" onclick="event.stopPropagation(); window._navigateToGame('${game.id}');">
                                ${badge}
                                ${imageSrc ? `<img src="${imageSrc}" alt="${titleSafe}" class="game-card-image" loading="lazy" decoding="async" />` : `<div class="game-card-image" style="background:#2a2a2a;display:flex;align-items:center;justify-content:center;font-size:3rem;">🎮</div>`}
                                <div class="game-card-body">
                                    ${gameCardChips(game)}
                                    <div class="game-card-title">${titleSafe}</div>
                                    ${game.shortDesc ? `<p class="game-card-desc">${esc(game.shortDesc)}</p>` : ''}
                                    <div class="game-card-actions">${vgdlBtn()}</div>
                                    <div class="game-card-meta">
                                        <span>${rating !== '0.0' ? `⭐ ${rating}` : 'بدون امتیاز'}</span>
                                        <button class="like-btn ${isLiked}" onclick="event.stopPropagation(); window._toggleLike('${game.id}');" title="لایک" aria-label="لایک ${titleSafe}">${isLiked ? '❤️' : '🤍'}</button>
                                    </div>
                                </div>
                            </div>`;
            }

            async function renderFeaturedSlider() {
                const slidesContainer = document.getElementById('featured-slides');
                const dotsContainer = document.getElementById('featured-dots');
                const games = await getGames();
                if (!games || games.length === 0) { document.getElementById('featured-slider').style.display = 'none'; return; }
                document.getElementById('featured-slider').style.display = 'block';
                const topGames = [...games].sort((a, b) => parseFloat(getGameRating(b)) - parseFloat(getGameRating(a))).slice(0, 16);
                if (topGames.length === 0) { document.getElementById('featured-slider').style.display = 'none'; return; }
                const pages = [];
                for (let i = 0; i < topGames.length; i += 4) pages.push(topGames.slice(i, i + 4));
                slidesContainer.innerHTML = pages.map(page => `
                        <div class="featured-slide">
                            <div class="featured-grid">
                                ${page.map((g, i) => buildFeaturedCard(g, i)).join('')}
                            </div>
                        </div>
                    `).join('');
                dotsContainer.innerHTML = pages.map((_, i) => `<button class="featured-dot ${i === 0 ? 'active' : ''}" onclick="window._featuredGoTo(${i})"></button>`).join('');
                featuredIndex = 0;
                updateFeaturedSlider();
                startFeaturedAutoPlay();
            }

            function startFeaturedAutoPlay() {
                if (featuredTimer) clearInterval(featuredTimer);
                featuredTimer = setInterval(() => {
                    const pages = document.querySelectorAll('.featured-slide');
                    if (pages.length > 1) { featuredIndex = (featuredIndex + 1) % pages.length; updateFeaturedSlider(); }
                }, 8000);
            }

            function updateFeaturedSlider() {
                const slidesContainer = document.getElementById('featured-slides');
                const dots = document.querySelectorAll('.featured-dot');
                slidesContainer.style.transform = `translateX(${featuredIndex * 100}%)`;
                dots.forEach((d, i) => d.classList.toggle('active', i === featuredIndex));
            }

            window._featuredNav = function(dir) {
                const slides = document.querySelectorAll('.featured-slide');
                if (slides.length <= 1) return;
                featuredIndex = (featuredIndex + dir + slides.length) % slides.length;
                updateFeaturedSlider();
                if (featuredTimer) clearInterval(featuredTimer);
                startFeaturedAutoPlay();
            };
            window._featuredGoTo = function(index) {
                featuredIndex = index;
                updateFeaturedSlider();
                if (featuredTimer) clearInterval(featuredTimer);
                startFeaturedAutoPlay();
            };

            const GAMES_PER_PAGE = 24;
            let gamesPage = 1;

            window._gamesPageTo = function(p) {
                gamesPage = p;
                renderGames();
                const grid = document.getElementById('games-grid');
                if (grid) grid.scrollIntoView({ behavior: 'smooth', block: 'start' });
            };

            window._clearGameFilters = function() {
                document.getElementById('search-input').value = '';
                document.getElementById('genre-filter').value = '';
                document.getElementById('sort-filter').value = 'newest';
                gamesPage = 1;
                renderGames();
            };

            async function renderGames() {
                const grid = document.getElementById('games-grid');
                const empty = document.getElementById('games-empty');
                const countBox = document.getElementById('games-count');
                const pagerBox = document.getElementById('games-pagination');
                const searchInput = document.getElementById('search-input').value.trim().toLowerCase();
                const genreFilter = document.getElementById('genre-filter').value;
                const sortFilter = document.getElementById('sort-filter').value;
                grid.innerHTML = '<div class="skeleton" style="height:220px;"></div>';
                let games = await getGames();
                const genreSelect = document.getElementById('genre-filter');
                const currentGenres = getAllGenres(games);
                if (genreSelect.options.length <= 1) {
                    const currentVal = genreSelect.value;
                    genreSelect.innerHTML = '<option value="">همه ژانرها</option>';
                    currentGenres.forEach(g => {
                        const opt = document.createElement('option');
                        opt.value = g; opt.textContent = g;
                        genreSelect.appendChild(opt);
                    });
                    genreSelect.value = currentVal || '';
                }
                if (searchInput) {
                    games = games.filter(g =>
                        (g.title && g.title.toLowerCase().includes(searchInput)) ||
                        (g.shortDesc && g.shortDesc.toLowerCase().includes(searchInput)) ||
                        (g.fullContent && g.fullContent.toLowerCase().includes(searchInput)) ||
                        (g.genre && g.genre.toLowerCase().includes(searchInput)) ||
                        (g.developer && g.developer.toLowerCase().includes(searchInput)) ||
                        (g.kravenMeta && g.kravenMeta.originalTitle && String(g.kravenMeta.originalTitle).toLowerCase().includes(searchInput))
                    );
                }
                function highlightMatch(text) {
                    if (!searchInput || !text) return esc(text || '');
                    const safe = esc(text);
                    const idx = text.toLowerCase().indexOf(searchInput);
                    if (idx === -1) return safe;
                    return esc(text.slice(0, idx)) + '<mark class="search-hl">' + esc(text.slice(idx, idx + searchInput.length)) + '</mark>' + esc(text.slice(idx + searchInput.length));
                }
                if (genreFilter) games = games.filter(g => g.genre === genreFilter);
                games.sort((a, b) => {
                    switch (sortFilter) {
                        case 'newest': return (parseInt(b.year) || 0) - (parseInt(a.year) || 0);
                        case 'oldest': return (parseInt(a.year) || 0) - (parseInt(b.year) || 0);
                        case 'rating': return parseFloat(getGameRating(b)) - parseFloat(getGameRating(a));
                        case 'likes': return (Number(b.likes) || (likes[b.id] ? 1 : 0)) - (Number(a.likes) || (likes[a.id] ? 1 : 0));
                        case 'updated': return new Date(b.updatedAt || b.createdAt || 0) - new Date(a.updatedAt || a.createdAt || 0);
                        case 'az': return String(a.title || '').localeCompare(String(b.title || ''), 'fa');
                        case 'za': return String(b.title || '').localeCompare(String(a.title || ''), 'fa');
                        default: return 0;
                    }
                });
                setTimeout(() => {
                    const totalPages = Math.max(1, Math.ceil(games.length / GAMES_PER_PAGE));
                    if (gamesPage > totalPages) gamesPage = totalPages;
                    const pageGames = games.slice((gamesPage - 1) * GAMES_PER_PAGE, gamesPage * GAMES_PER_PAGE);
                    if (games.length === 0) {
                        grid.innerHTML = '';
                        empty.style.display = 'block';
                        if (countBox) countBox.textContent = '';
                        if (pagerBox) pagerBox.innerHTML = '';
                    } else {
                        empty.style.display = 'none';
                        if (countBox) countBox.textContent = `${games.length.toLocaleString('fa-IR')} بازی` + (searchInput || genreFilter ? ' یافت شد' : '');
                        if (pagerBox) {
                            if (totalPages > 1) {
                                pagerBox.innerHTML = `
                                <button class="page-btn ${gamesPage === 1 ? 'disabled' : ''}" ${gamesPage > 1 ? `onclick="window._gamesPageTo(${gamesPage - 1})"` : ''} aria-label="صفحه قبل">‹</button>
                                ${Array.from({ length: totalPages }, (_, i) => i + 1)
                                    .filter(p => p === 1 || p === totalPages || Math.abs(p - gamesPage) <= 2)
                                    .map((p, idx, arr) => (idx > 0 && p - arr[idx - 1] > 1 ? '<span class="page-ellipsis">…</span>' : '') + `<button class="page-btn ${p === gamesPage ? 'active' : ''}" onclick="window._gamesPageTo(${p})">${p.toLocaleString('fa-IR')}</button>`)
                                    .join('')}
                                <button class="page-btn ${gamesPage === totalPages ? 'disabled' : ''}" ${gamesPage < totalPages ? `onclick="window._gamesPageTo(${gamesPage + 1})"` : ''} aria-label="صفحه بعد">›</button>`;
                            } else {
                                pagerBox.innerHTML = '';
                            }
                        }
                        grid.innerHTML = pageGames.map((game, index) => {
                            const isLiked = likes[game.id] ? 'liked' : '';
                            const rating = getGameRating(game);
                            const imageSrc = game.imageData || '';
                            const badge = getGameBadge(game);
                            const isComparing = compareList.includes(game.id) ? 'checked' : '';
                            const titleSafe = esc(game.title || 'بدون عنوان');
                            return `
                            <div class="game-card card-visible" style="animation-delay:${index * 0.08}s;position:relative;" onclick="event.stopPropagation(); window._navigateToGame('${game.id}');">
                                ${badge}
                                <label class="compare-checkbox-wrap" onclick="event.stopPropagation();">
                                    <input type="checkbox" ${isComparing} onchange="window._toggleCompare('${game.id}', this.checked)" /> مقایسه
                                </label>
                                ${imageSrc ? `<img src="${imageSrc}" alt="${titleSafe}" class="game-card-image" loading="lazy" decoding="async" />` : `<div class="game-card-image" style="background:#2a2a2a;display:flex;align-items:center;justify-content:center;font-size:3rem;">🎮</div>`}
                                <div class="game-card-body">
                                    ${gameCardChips(game)}
                                    <div class="game-card-title">${highlightMatch(game.title) || 'بدون عنوان'}</div>
                                    ${game.shortDesc ? `<p class="game-card-desc">${highlightMatch(game.shortDesc)}</p>` : ''}
                                    <div class="game-card-actions">${vgdlBtn()}</div>
                                    <div class="game-card-meta">
                                        <span>${rating !== '0.0' ? `⭐ ${rating}` : 'بدون امتیاز'}</span>
                                        <button class="like-btn ${isLiked}" onclick="event.stopPropagation(); window._toggleLike('${game.id}');" title="لایک" aria-label="لایک ${titleSafe}">${isLiked ? '❤️' : '🤍'}</button>
                                    </div>
                                </div>
                            </div>`;
                        }).join('');
                    }
                }, 300);
            }

            function newsCover(n) { return n.imageData || n.imageUrl || ''; }
            function newsExcerpt(n) {
                const raw = n.shortSummary || n.text || n.desc || '';
                return String(raw).replace(/\s+/g, ' ').trim().slice(0, 180);
            }
            async function renderNews() {
                const list = document.getElementById('news-list');
                const empty = document.getElementById('news-empty');
                const news = await dbGetAll(STORES.news);
                if (!news || news.length === 0) { list.innerHTML = ''; empty.style.display = 'block'; return; }
                empty.style.display = 'none';
                news.sort((a, b) => new Date(b.pubDate || b.createdAt || 0) - new Date(a.pubDate || a.createdAt || 0));
                list.innerHTML = news.map((n, i) => {
                    const cover = newsCover(n);
                    const title = esc(n.title || 'بدون عنوان');
                    const date = n.pubDate || n.createdAt;
                    const cat = n.category || '';
                    const tags = Array.isArray(n.tags) ? n.tags.slice(0, 3) : [];
                    return `
                    <article class="news-card reveal visible" data-news-id="${esc(n.id)}" onclick="window._openNews('${esc(n.id)}')" tabindex="0" role="link" aria-label="${title}" onkeydown="if(event.key==='Enter'){event.preventDefault();window._openNews('${esc(n.id)}');}">
                        ${cover ? `<div class="news-card-media"><img src="${esc(cover)}" alt="${title}" loading="lazy" decoding="async" /></div>` : ''}
                        <div class="news-card-body">
                            <div class="news-card-meta">
                                ${cat ? `<span class="badge badge-new">${esc(cat)}</span>` : ''}
                                ${date ? `<span class="news-card-date">📅 ${fmtDate(date)}</span>` : ''}
                                ${n.readingTime ? `<span class="news-card-date">⏱ ${Number(n.readingTime).toLocaleString('fa-IR')} دقیقه مطالعه</span>` : ''}
                            </div>
                            <h2 class="news-card-title">${title}</h2>
                            ${newsExcerpt(n) ? `<p class="news-card-excerpt">${esc(newsExcerpt(n))}…</p>` : ''}
                            ${(tags.length || n.sourceName) ? `<div class="news-card-tags">${tags.map(t => `<span class="tag">#${esc(t)}</span>`).join('')}${n.sourceName ? `<span class="tag">🔗 ${esc(n.sourceName)}</span>` : ''}</div>` : ''}
                            <span class="news-card-more">ادامه مطلب ›</span>
                        </div>
                    </article>`;
                }).join('');
            }
            window._openNews = function(id) {
                currentNewsId = id;
                navigateTo('news-detail');
            };

            // Turns stored plain text into safe paragraphs (newlines -> <br>).
            function richText(s) {
                return esc(s == null ? '' : String(s)).replace(/\r?\n/g, '<br>');
            }

            /* ---------- SEO helpers (meta + JSON-LD) ---------- */
            function setMeta(property, content) {
                if (!content) return;
                let tag = document.querySelector(`meta[property="${property}"]`) || document.querySelector(`meta[name="${property}"]`);
                if (!tag) {
                    tag = document.createElement('meta');
                    tag.setAttribute(property.startsWith('og:') || property.startsWith('article:') ? 'property' : 'name', property);
                    document.head.appendChild(tag);
                }
                tag.setAttribute('content', content);
            }
            function setJsonLd(obj) {
                let el = document.getElementById('dynamic-jsonld');
                if (!el) {
                    el = document.createElement('script');
                    el.type = 'application/ld+json';
                    el.id = 'dynamic-jsonld';
                    document.head.appendChild(el);
                }
                el.textContent = JSON.stringify(obj);
            }
            const PAGE_TITLES = {
                home: 'Kraven Game | پلتفرم معرفی بازی‌های ویدیویی',
                favorites: 'علاقه‌مندی‌ها | Kraven Game',
                news: 'اخبار گیم | Kraven Game',
                'news-detail': 'خبر | Kraven Game',
                about: 'درباره ما | Kraven Game',
                contact: 'تماس با ما | Kraven Game',
                faq: 'سوالات متداول | Kraven Game',
                tutorials: 'آموزش‌ها | Kraven Game',
                compare: 'مقایسه بازی‌ها | Kraven Game',
                calendar: 'تقویم عرضه | Kraven Game',
                profile: 'پروفایل | Kraven Game',
                bookmarks: 'بوکمارک‌ها | Kraven Game',
                requests: 'درخواست بازی | Kraven Game',
                admin: 'پنل مدیریت | Kraven Game',
                'game-detail': 'بازی | Kraven Game'
            };

            async function renderNewsDetail(id) {
                const container = document.getElementById('news-detail-content');
                if (!container) return;
                const news = await dbGetAll(STORES.news);
                const n = news.find(x => x.id === id);
                if (!n) {
                    container.innerHTML = '<div class="empty-state"><div class="icon">📰</div><h3>خبر یافت نشد</h3><p>ممکن است این خبر حذف شده باشد.</p><button class="btn btn-primary" onclick="window._go(\'news\')">بازگشت به اخبار</button></div>';
                    document.title = 'خبر یافت نشد | Kraven Game';
                    return;
                }
                document.getElementById('news-breadcrumb-title').textContent = n.title || 'خبر';
                const cover = newsCover(n);
                const date = n.pubDate || n.createdAt;
                const tags = Array.isArray(n.tags) ? n.tags : [];
                const relatedGames = Array.isArray(n.relatedGames) ? n.relatedGames : [];
                const games = await getGames();
                const linkedGames = relatedGames.map(t => games.find(g => g.title === t || g.kravenMeta && g.kravenMeta.originalTitle === t)).filter(Boolean).slice(0, 4);
                const relatedNews = news.filter(x => x.id !== n.id && ((x.category && x.category === n.category) || (Array.isArray(x.tags) && x.tags.some(t => tags.includes(t))))).slice(0, 3);
                document.title = `${n.title || 'خبر'} | Kraven Game`;
                setMeta('og:title', n.title || 'خبر');
                setMeta('og:description', n.seoDesc || n.shortSummary || newsExcerpt(n) || '');
                if (cover) setMeta('og:image', cover.startsWith('data:') ? '' : cover);
                setJsonLd({
                    '@context': 'https://schema.org', '@type': 'NewsArticle',
                    headline: n.title || '', description: n.seoDesc || newsExcerpt(n) || '',
                    image: cover && !cover.startsWith('data:') ? [cover] : undefined,
                    datePublished: date || undefined, dateModified: date || undefined,
                    author: n.author ? { '@type': 'Person', name: n.author } : undefined,
                    articleSection: n.category || undefined
                });
                container.innerHTML = `
                <article class="game-detail news-detail">
                    ${cover ? `<div class="news-detail-hero"><img src="${esc(cover)}" alt="${esc(n.title || 'خبر')}" decoding="async" /></div>` : ''}
                    <div class="news-detail-header">
                        <h1>${esc(n.title || 'بدون عنوان')}</h1>
                        <div class="news-card-meta">
                            ${n.category ? `<span class="badge badge-new">${esc(n.category)}</span>` : ''}
                            ${n.author ? `<span class="news-card-date">✍️ ${esc(n.author)}</span>` : ''}
                            ${date ? `<span class="news-card-date">📅 ${fmtDate(date)}</span>` : ''}
                            ${n.readingTime ? `<span class="news-card-date">⏱ ${Number(n.readingTime).toLocaleString('fa-IR')} دقیقه مطالعه</span>` : ''}
                        </div>
                    </div>
                    ${n.shortSummary ? `<div class="news-detail-lead">${esc(n.shortSummary)}</div>` : ''}
                    ${n.text ? `<div class="news-detail-content"><p>${richText(n.text)}</p></div>` : ''}
                    ${(tags.length || n.sourceName || n.sourceUrl) ? `
                    <div class="game-detail-section">
                        ${tags.length ? `<h3>🏷️ برچسب‌ها</h3><div class="tags">${tags.map(t => `<span class="tag">#${esc(t)}</span>`).join('')}</div>` : ''}
                        ${n.sourceName ? `<p style="margin-top:12px;font-size:0.85rem;">🔗 منبع: ${n.sourceUrl ? `<a href="${esc(n.sourceUrl)}" target="_blank" rel="noopener">${esc(n.sourceName)}</a>` : esc(n.sourceName)}</p>` : ''}
                    </div>` : ''}
                    ${linkedGames.length ? `
                    <div class="game-detail-section">
                        <h3>🎮 بازی‌های مرتبط</h3>
                        <div class="games-grid">${linkedGames.map(g => `
                            <div class="game-card" onclick="window._navigateToGame('${g.id}')">
                                ${g.imageData ? `<img src="${g.imageData}" alt="${esc(g.title)}" class="game-card-image" loading="lazy" />` : `<div class="game-card-image" style="background:#2a2a2a;display:flex;align-items:center;justify-content:center;font-size:2rem;">🎮</div>`}
                                <div class="game-card-body">${gameCardChips(g)}<div class="game-card-title">${esc(g.title || '')}</div><div class="game-card-actions">${vgdlBtn()}</div></div>
                            </div>`).join('')}
                        </div>
                    </div>` : ''}
                    ${relatedNews.length ? `
                    <div class="game-detail-section">
                        <h3>📰 اخبار مرتبط</h3>
                        ${relatedNews.map(r => `
                            <div class="related-news-item" onclick="window._openNews('${esc(r.id)}')">
                                ${newsCover(r) ? `<img src="${esc(newsCover(r))}" alt="" loading="lazy" />` : ''}
                                <div><strong>${esc(r.title || '')}</strong><span>${fmtDate(r.pubDate || r.createdAt)}</span></div>
                            </div>`).join('')}
                    </div>` : ''}
                    <div style="text-align:center;margin-top:var(--spacing-lg);">
                        <button class="btn btn-primary" onclick="window._go('news')">بازگشت به اخبار</button>
                    </div>
                </article>`;
            }

            window._navigateToGame = function(id) {
                currentGameId = id;
                recordView(id);
                navigateTo('game-detail');
            };
            window._toggleLike = function(gameId) {
                if (likes[gameId]) { delete likes[gameId]; } else { likes[gameId] = true; }
                localStorage.setItem('kraven_likes', JSON.stringify(likes));
                renderGames();
                if (currentPage === 'favorites') renderFavorites();
                if (currentPage === 'game-detail') renderGameDetail(currentGameId);
                updateAdminStats();
            };
            function recordRating(gameId, value) {
                if (!userRatings[gameId]) userRatings[gameId] = [];
                userRatings[gameId].push(value);
                localStorage.setItem('kraven_user_ratings', JSON.stringify(userRatings));
                dbGet(STORES.games, gameId).then(game => {
                    if (game) {
                        if (!game.userRatings) game.userRatings = [];
                        game.userRatings.push(value);
                        dbPut(STORES.games, game);
                    }
                });
            }
            function recordView(gameId) {
                if (!views[gameId]) views[gameId] = 0;
                views[gameId]++;
                localStorage.setItem('kraven_views', JSON.stringify(views));
                dbPut(STORES.views, { gameId: gameId, count: views[gameId] });
            }

            async function renderGameDetail(gameId) {
                const container = document.getElementById('game-detail-content');
                const game = await getGameById(gameId);
                if (!game) {
                    container.innerHTML = '<div class="empty-state"><div class="icon">🎮</div><h3>بازی یافت نشد</h3><p>ممکن است این بازی حذف شده باشد.</p><button class="btn btn-primary" onclick="window._go(\'home\')">بازگشت به خانه</button></div>';
                    document.title = 'بازی یافت نشد | Kraven Game';
                    return;
                }
                document.getElementById('breadcrumb-title').textContent = game.title || 'جزئیات بازی';
                const rating = getGameRating(game);
                const ratingCount = getGameRatingCount(game);
                const similarGames = await getSimilarGames(game);
                const galleryImages = game.gallery && game.gallery.length > 0 ? game.gallery : (game.imageData ? [game.imageData] : []);
                currentGalleryImages = galleryImages;
                const downloadLinks = game.downloadLinks || [];
                const titleSafe = esc(game.title || 'بدون عنوان');
                document.title = `${game.title || 'بازی'} | Kraven Game`;
                setMeta('og:title', game.title || 'بازی');
                setMeta('og:description', game.shortDesc || '');
                if (game.imageData && !game.imageData.startsWith('data:')) setMeta('og:image', game.imageData);
                setJsonLd({
                    '@context': 'https://schema.org', '@type': 'VideoGame',
                    name: game.title || '', description: game.shortDesc || game.fullContent ? String(game.shortDesc || '').slice(0, 300) : undefined,
                    genre: game.genre || undefined, gamePlatform: game.platform || undefined,
                    datePublished: (game.kravenMeta && game.kravenMeta.releaseDate) || game.year || undefined,
                    author: game.developer ? { '@type': 'Organization', name: game.developer } : undefined,
                    publisher: (game.kravenMeta && game.kravenMeta.publisher) ? { '@type': 'Organization', name: game.kravenMeta.publisher } : undefined,
                    image: game.imageData && !game.imageData.startsWith('data:') ? game.imageData : undefined,
                    aggregateRating: (rating !== '0.0' && ratingCount > 0) ? { '@type': 'AggregateRating', ratingValue: rating, ratingCount: ratingCount, bestRating: '5' } : undefined
                });
                const infoRows = [
                    game.year && `📅 سال انتشار: ${esc(String(game.year))}`,
                    game.developer && `🏢 سازنده: ${esc(game.developer)}`,
                    (game.kravenMeta && game.kravenMeta.publisher) && `Publisher: ${esc(game.kravenMeta.publisher)}`,
                    game.size && `💾 حجم بازی: ${esc(game.size)}`,
                    game.platform && `🖥️ پلتفرم: ${esc(game.platform)}`,
                    game.mode && `🎮 حالت بازی: ${esc(game.mode)}`,
                    game.status && `📌 وضعیت: ${game.status === 'released' ? 'عرضه شده' : 'به زودی'}`,
                    (game.kravenMeta && game.kravenMeta.ageRating) && `🔞 رده سنی: ${esc(game.kravenMeta.ageRating)}`
                ].filter(Boolean);
                container.innerHTML = `
                <div class="game-detail reveal visible">
                    <div class="game-detail-header" data-sec="header">
                        ${game.imageData ? `<img src="${game.imageData}" alt="${titleSafe}" class="game-detail-image" loading="lazy" decoding="async" style="cursor:zoom-in;" onclick="window._openLightbox(0)" />` : ''}
                        <div class="game-detail-info">
                            <h2>${titleSafe}</h2>
                            <div class="tags">
                                <span class="tag">${esc(game.genre || 'نامشخص')}</span>
                                ${game.platform ? `<span class="tag">${esc(game.platform)}</span>` : ''}
                                ${game.mode ? `<span class="tag">${esc(game.mode)}</span>` : ''}
                                ${game.status ? `<span class="tag">${game.status === 'released' ? 'عرضه شده' : 'به زودی'}</span>` : ''}
                                ${game.year ? `<span class="tag">${esc(String(game.year))}</span>` : ''}
                            </div>
                            <div class="star-rating">
                                ${[1,2,3,4,5].map(i => `<span class="star ${i <= Math.round(parseFloat(rating)) ? 'active' : ''}" onclick="window._rateGame('${gameId}', ${i})">★</span>`).join('')}
                                <span class="rating-info">${rating !== '0.0' ? rating : 'بدون امتیاز'} (${ratingCount} رای)</span>
                            </div>
                            <div style="display:flex;gap:var(--spacing-sm);flex-wrap:wrap;margin-top:var(--spacing-md);align-items:center;">
                                <button class="like-btn ${likes[gameId] ? 'liked' : ''}" onclick="window._toggleLike('${gameId}')" style="font-size:2rem;" aria-label="لایک ${titleSafe}">${likes[gameId] ? '❤️' : '🤍'}</button>
                                ${downloadLinks.length > 0 ? downloadLinks.map(link => `<a href="${esc(link)}" target="_blank" rel="noopener" class="download-btn">⬇️ دانلود</a>`).join('') : ''}
                                ${vgdlBtn(true)}
                                ${(game.kravenMeta && game.kravenMeta.trailer && game.kravenMeta.trailer.url) ? `<a class="trailer-btn" href="${esc(game.kravenMeta.trailer.url)}" target="_blank" rel="noopener" style="font-size:0.95rem;padding:12px 22px;">🎬 تریلر</a>` : ''}
                            </div>
                            <div class="game-detail-vote" style="margin-top:var(--spacing-sm);font-size:0.85rem;color:var(--text-muted);">🔗 لینک دانلود بازی: <a href="${VGDL_URL}" target="_blank" rel="noopener" style="color:var(--primary);font-weight:700;">vgdl.ir</a></div>
                        </div>
                    </div>
                    ${game.shortDesc ? `<div class="game-detail-section" data-sec="desc"><h3>📝 توضیحات</h3><p>${richText(game.shortDesc)}</p></div>` : ''}
                    ${game.fullContent ? `<div class="game-detail-section" data-sec="review"><h3>📖 نقد و بررسی کامل</h3><p>${richText(game.fullContent)}</p></div>` : ''}
                    ${infoRows.length ? `
                    <div class="game-detail-section" data-sec="info">
                        <h3>📋 اطلاعات بازی</h3>
                        <p>${infoRows.join('<br />')}</p>
                    </div>` : ''}
                    ${(game.kravenMeta && Array.isArray(game.kravenMeta.features) && game.kravenMeta.features.length) ? `
                    <div class="game-detail-section" data-sec="features">
                        <h3>✨ ویژگی‌های اصلی</h3>
                        <ul class="feature-list">${game.kravenMeta.features.map(f => `<li>${esc(f)}</li>`).join('')}</ul>
                    </div>` : ''}
                    ${galleryImages.length > 0 ? `<div class="game-detail-section" data-sec="gallery"><h3>🖼️ گالری تصاویر</h3><div class="gallery-grid">${galleryImages.map((img, gi) => `<img src="${esc(img)}" alt="${titleSafe}" onclick="window._openLightbox(${gi})" loading="lazy" decoding="async" style="cursor:zoom-in;" />`).join('')}</div></div>` : ''}
                    ${game.installGuide ? `<div class="game-detail-section" data-sec="install"><h3>🔧 راهنمای نصب</h3><p>${richText(game.installGuide)}</p></div>` : ''}
                    ${game.minRequirements ? `<div class="game-detail-section" data-sec="minreq"><h3>💻 حداقل سیستم مورد نیاز</h3><p>${richText(game.minRequirements)}</p></div>` : ''}
                    ${game.recRequirements ? `<div class="game-detail-section" data-sec="recreq"><h3>🚀 سیستم پیشنهادی</h3><p>${richText(game.recRequirements)}</p></div>` : ''}
                    ${similarGames.length > 0 ? `
                    <div class="game-detail-section" data-sec="similar">
                        <h3>🎮 بازی‌های مشابه</h3>
                        <div class="games-grid" style="grid-template-columns:1fr;">
                            ${similarGames.map(g => `
                                <div class="game-card" onclick="window._navigateToGame('${g.id}')">
                                    ${g.imageData ? `<img src="${g.imageData}" alt="${esc(g.title)}" class="game-card-image" loading="lazy" />` : `<div class="game-card-image" style="background:#2a2a2a;display:flex;align-items:center;justify-content:center;font-size:2rem;">🎮</div>`}
                                    <div class="game-card-body">
                                        ${gameCardChips(g)}
                                        <div class="game-card-title">${esc(g.title || 'بدون عنوان')}</div>
                                        <div class="game-card-actions">${vgdlBtn()}</div>
                                    </div>
                                </div>
                            `).join('')}
                        </div>
                    </div>` : ''}
                    <div class="game-detail-section" data-sec="comments">
                        <div id="game-social"></div>
                    </div>
                </div>`;
                renderGameSocial(gameId, game);
                recordRecentView(gameId);
            }
            window._rateGame = function(gameId, value) {
                recordRating(gameId, value);
                renderGameDetail(gameId);
                showToast('امتیاز شما ثبت شد!', 'success');
                updateAdminStats();
            };
            window._openImage = function(src) { window.open(src, '_blank'); };

            /* ===== Lightbox ===== */
            window._openLightbox = function(index) {
                if (!currentGalleryImages || currentGalleryImages.length === 0) return;
                currentLightboxIndex = index;
                updateLightbox();
                document.getElementById('lightbox-overlay').classList.add('open');
            };
            function updateLightbox() {
                const imgs = currentGalleryImages;
                if (!imgs || imgs.length === 0) return;
                currentLightboxIndex = (currentLightboxIndex + imgs.length) % imgs.length;
                document.getElementById('lightbox-img').src = imgs[currentLightboxIndex];
                document.getElementById('lightbox-counter').textContent = imgs.length > 1 ? `${currentLightboxIndex + 1} / ${imgs.length}` : '';
                document.querySelectorAll('.lightbox-nav').forEach(b => b.style.display = imgs.length > 1 ? 'flex' : 'none');
            }
            function closeLightbox() { document.getElementById('lightbox-overlay').classList.remove('open'); }

            /* ===== Compare feature ===== */
            function saveCompareList() { localStorage.setItem('kraven_compare', JSON.stringify(compareList)); }
            window._toggleCompare = function(gameId, checked) {
                if (checked) {
                    if (compareList.length >= 3) { showToast('حداکثر ۳ بازی قابل مقایسه است', 'warning'); renderGames(); return; }
                    if (!compareList.includes(gameId)) compareList.push(gameId);
                } else {
                    compareList = compareList.filter(id => id !== gameId);
                }
                saveCompareList();
                updateCompareBar();
            };
            async function updateCompareBar() {
                const bar = document.getElementById('compare-bar');
                const gamesDiv = document.getElementById('compare-bar-games');
                if (compareList.length === 0) { bar.classList.remove('visible'); return; }
                bar.classList.add('visible');
                const allGames = await getGames();
                const selected = allGames.filter(g => compareList.includes(g.id));
                gamesDiv.innerHTML = selected.map(g => `<span class="tag">${g.title}</span>`).join('');
            }
            document.addEventListener('DOMContentLoaded', () => {
                const clearBtn = document.getElementById('compare-clear-btn');
                const viewBtn = document.getElementById('compare-view-btn');
                if (clearBtn) clearBtn.addEventListener('click', () => { compareList = []; saveCompareList(); updateCompareBar(); renderGames(); });
                if (viewBtn) viewBtn.addEventListener('click', () => { navigateTo('compare'); });
                updateCompareBar();
                const lbClose = document.getElementById('lightbox-close');
                const lbPrev = document.getElementById('lightbox-prev');
                const lbNext = document.getElementById('lightbox-next');
                const lbOverlay = document.getElementById('lightbox-overlay');
                if (lbClose) lbClose.addEventListener('click', closeLightbox);
                if (lbOverlay) lbOverlay.addEventListener('click', (e) => { if (e.target === lbOverlay) closeLightbox(); });
                if (lbPrev) lbPrev.addEventListener('click', () => { currentLightboxIndex--; updateLightbox(); });
                if (lbNext) lbNext.addEventListener('click', () => { currentLightboxIndex++; updateLightbox(); });
                document.addEventListener('keydown', (e) => {
                    if (!document.getElementById('lightbox-overlay').classList.contains('open')) return;
                    if (e.key === 'Escape') closeLightbox();
                    if (e.key === 'ArrowLeft') { currentLightboxIndex++; updateLightbox(); }
                    if (e.key === 'ArrowRight') { currentLightboxIndex--; updateLightbox(); }
                });

                /* PWA: register service worker + install prompt */
                if ('serviceWorker' in navigator) {
                    window.addEventListener('load', () => {
                        navigator.serviceWorker.register('sw.js').catch(() => {});
                    });
                }
                window.addEventListener('beforeinstallprompt', (e) => {
                    e.preventDefault();
                    deferredInstallPrompt = e;
                    const btn = document.getElementById('install-app-btn');
                    if (btn) btn.classList.add('visible');
                });
                const installBtn = document.getElementById('install-app-btn');
                if (installBtn) {
                    installBtn.addEventListener('click', async () => {
                        if (!deferredInstallPrompt) return;
                        deferredInstallPrompt.prompt();
                        await deferredInstallPrompt.userChoice;
                        deferredInstallPrompt = null;
                        installBtn.classList.remove('visible');
                    });
                }
                window.addEventListener('appinstalled', () => {
                    const btn = document.getElementById('install-app-btn');
                    if (btn) btn.classList.remove('visible');
                    showToast('برنامه با موفقیت نصب شد 🎉', 'success');
                });
            });
            async function renderComparePage() {
                const container = document.getElementById('compare-content');
                if (compareList.length < 2) {
                    container.innerHTML = '<div class="empty-state"><div class="icon">⚖️</div><h3>حداقل ۲ بازی انتخاب کنید</h3><p>از صفحه اصلی، روی چک‌باکس «مقایسه» بازی‌ها کلیک کنید</p></div>';
                    return;
                }
                const allGames = await getGames();
                const selected = allGames.filter(g => compareList.includes(g.id));
                const rows = [
                    { label: 'تصویر', render: g => g.imageData ? `<img src="${g.imageData}" loading="lazy" alt="${esc(g.title || '')}" />` : '-' },
                    { label: 'عنوان', render: g => esc(g.title || '-') },
                    { label: 'ژانر', render: g => esc(g.genre || '-') },
                    { label: 'امتیاز', render: g => `⭐ ${getGameRating(g)}` },
                    { label: 'سال', render: g => esc(String(g.year || '-')) },
                    { label: 'سازنده', render: g => esc(g.developer || '-') },
                    { label: 'حجم', render: g => esc(g.size || '-') },
                    { label: 'پلتفرم', render: g => esc(g.platform || '-') },
                    { label: 'حالت بازی', render: g => esc(g.mode || '-') },
                    { label: 'حداقل سیستم', render: g => esc(g.minRequirements || '-') },
                    { label: 'سیستم پیشنهادی', render: g => esc(g.recRequirements || '-') },
                    { label: '', render: g => `<button class="compare-remove-btn" onclick="window._toggleCompare('${g.id}', false); window._navigateAfterRemove()">✕ حذف</button>` }
                ];
                container.innerHTML = `
                    <div style="overflow-x:auto;">
                    <table class="compare-table">
                        ${rows.map(row => `
                            <tr>
                                <th>${row.label}</th>
                                ${selected.map(g => `<td>${row.render(g)}</td>`).join('')}
                            </tr>
                        `).join('')}
                    </table>
                    </div>`;
            }
            window._navigateAfterRemove = function() { updateCompareBar(); renderComparePage(); };
            async function getSimilarGames(game) {
                const games = await getGames();
                return games.filter(g => g.id !== game.id && g.genre === game.genre).slice(0, 4);
            }

            async function renderFavorites() {
                const grid = document.getElementById('favorites-grid');
                const empty = document.getElementById('favorites-empty');
                const likedIds = Object.keys(likes).filter(k => likes[k]);
                if (likedIds.length === 0) { grid.innerHTML = ''; empty.style.display = 'block'; return; }
                empty.style.display = 'none';
                const games = await getGames();
                const likedGames = games.filter(g => likedIds.includes(g.id));
                grid.innerHTML = likedGames.map((game, index) => {
                    const rating = getGameRating(game);
                    const badge = getGameBadge(game);
                    const titleSafe = esc(game.title || 'بدون عنوان');
                    return `
                    <div class="game-card card-visible" style="animation-delay:${index * 0.08}s;" onclick="window._navigateToGame('${game.id}')">
                        ${badge}
                        ${game.imageData ? `<img src="${game.imageData}" alt="${titleSafe}" class="game-card-image" loading="lazy" />` : `<div class="game-card-image" style="background:#2a2a2a;display:flex;align-items:center;justify-content:center;font-size:2rem;">🎮</div>`}
                        <div class="game-card-body">
                            ${gameCardChips(game)}
                            <div class="game-card-title">${titleSafe}</div>
                            ${game.shortDesc ? `<p class="game-card-desc">${esc(game.shortDesc)}</p>` : ''}
                            <div class="game-card-actions">${vgdlBtn()}</div>
                            <div class="game-card-meta">
                                <span>${rating !== '0.0' ? `⭐ ${rating}` : 'بدون امتیاز'}</span>
                                <button class="like-btn liked" onclick="event.stopPropagation(); window._toggleLike('${game.id}');">❤️</button>
                            </div>
                        </div>
                    </div>`;
                }).join('');
            }

            async function renderFAQ() {
                const list = document.getElementById('faq-list');
                const faqs = await dbGetAll(STORES.faq);
                if (!faqs || faqs.length === 0) {
                    list.innerHTML = '<div class="empty-state"><div class="icon">❓</div><h3>سوالی ثبت نشده است</h3></div>';
                    return;
                }
                const categories = {};
                faqs.forEach(f => {
                    const cat = f.category || 'عمومی';
                    if (!categories[cat]) categories[cat] = [];
                    categories[cat].push(f);
                });
                list.innerHTML = Object.entries(categories).map(([cat, items]) => `
                    <div class="game-detail-section">
                        <h3>${esc(cat)}</h3>
                        ${items.map(f => `
                            <div class="accordion-item" id="faq-item-${f.id}">
                                <div class="accordion-header" onclick="window._toggleAccordion('${f.id}')">
                                    <span>${esc(f.q || '')}</span>
                                    <span class="arrow">▼</span>
                                </div>
                                <div class="accordion-body">
                                    <div class="accordion-body-content">${esc(f.a || '')}</div>
                                </div>
                            </div>
                        `).join('')}
                    </div>
                `).join('');
            }
            window._toggleAccordion = function(id) {
                const item = document.getElementById(`faq-item-${id}`);
                if (item) item.classList.toggle('open');
            };

            async function renderTutorials() {
                const list = document.getElementById('tutorials-list');
                const tutorials = await dbGetAll(STORES.tutorials);
                if (!tutorials || tutorials.length === 0) {
                    list.innerHTML = '<div class="empty-state"><div class="icon">📚</div><h3>آموزشی ثبت نشده است</h3></div>';
                    return;
                }
                list.innerHTML = tutorials.map(t => `
                    <div class="accordion-item" id="tutorial-item-${t.id}">
                        <div class="accordion-header" onclick="window._toggleTutorial('${t.id}')">
                            <span>📚 ${esc(t.title || 'بدون عنوان')}</span>
                            <span class="arrow">▼</span>
                        </div>
                        <div class="accordion-body">
                            <div class="accordion-body-content">
                                ${t.category ? `<p><strong>دسته: </strong>${esc(t.category)}</p>` : ''}
                                <p style="margin-top:8px;">${esc(t.content || '')}</p>
                            </div>
                        </div>
                    </div>
                `).join('');
            }
            window._toggleTutorial = function(id) {
                const item = document.getElementById(`tutorial-item-${id}`);
                if (item) item.classList.toggle('open');
            };

            function initContactForm() {
                document.getElementById('contact-form').addEventListener('submit', async (e) => {
                    e.preventDefault();
                    const name = document.getElementById('contact-name').value.trim();
                    const email = document.getElementById('contact-email').value.trim();
                    const subject = document.getElementById('contact-subject').value;
                    const message = document.getElementById('contact-message').value.trim();
                    if (!name || !email || !subject || !message) { showToast('لطفاً همه فیلدها را پر کنید', 'error'); return; }
                    const msg = { name, email, subject, message, date: new Date().toISOString(), read: false };
                    await dbAdd(STORES.messages, msg);
                    showToast('پیام شما با موفقیت ارسال شد', 'success');
                    e.target.reset();
                    updateAdminStats();
                });
            }

            function initChatbot() {
                const toggleBtn = document.getElementById('chatbot-toggle');
                const panel = document.getElementById('chatbot-panel');
                const closeBtn = document.getElementById('chatbot-close');
                const messages = document.getElementById('chatbot-messages');
                const quickReplies = document.getElementById('quick-replies');
                const typingIndicator = document.getElementById('typing-indicator');
                toggleBtn.addEventListener('click', () => {
                    panel.classList.toggle('open');
                    if (panel.classList.contains('open')) { loadQuickReplies(); }
                });
                closeBtn.addEventListener('click', () => panel.classList.remove('open'));
                async function loadQuickReplies() {
                    const responses = await dbGetAll(STORES.chatbot);
                    if (responses && responses.length > 0) {
                        quickReplies.innerHTML = responses.map(r => `
                            <button class="quick-reply-btn" onclick="window._quickReply('${r.id}')">${r.q || ''}</button>
                        `).join('');
                    } else {
                        quickReplies.innerHTML = `
                            <button class="quick-reply-btn" onclick="window._quickReply('default1')">📥 چطور دانلود کنم؟</button>
                            <button class="quick-reply-btn" onclick="window._quickReply('default2')">🎮 بازی جدید چطور اضافه کنم؟</button>
                            <button class="quick-reply-btn" onclick="window._quickReply('default3')">📞 چطور تماس بگیرم؟</button>
                        `;
                    }
                }
                window._quickReply = async function(id) {
                    const responses = await dbGetAll(STORES.chatbot);
                    let reply = 'متوجه نشدم!';
                    if (id === 'default1') reply = 'برای دانلود بازی، وارد صفحه بازی شوید و روی دکمه دانلود کلیک کنید.';
                    else if (id === 'default2') reply = 'برای اضافه کردن بازی، از پنل مدیریت وارد شوید.';
                    else if (id === 'default3') reply = 'از صفحه تماس با ما می‌توانید پیام ارسال کنید.';
                    else {
                        const match = responses.find(r => String(r.id) === String(id));
                        if (match) reply = match.a || 'پاسخی ثبت نشده';
                    }
                    addMessage('user', 'سوال انتخابی');
                    typingIndicator.classList.add('active');
                    setTimeout(() => {
                        typingIndicator.classList.remove('active');
                        addMessage('bot', reply);
                    }, 600);
                };
                function addMessage(type, text) {
                    const div = document.createElement('div');
                    div.className = `chat-message ${type}`;
                    div.textContent = text;
                    messages.appendChild(div);
                    messages.scrollTop = messages.scrollHeight;
                }
                addMessage('bot', '👋 سلام! روی سوالات زیر کلیک کنید:');
                loadQuickReplies();
            }

            function updateAdminStats() {
                Promise.all([
                    dbGetAll(STORES.games),
                    dbGetAll(STORES.news),
                    dbGetAll(STORES.messages)
                ]).then(([games, news, messages]) => {
                    const totalLikes = Object.keys(likes).filter(k => likes[k]).length;
                    const totalViews = Object.values(views).reduce((a, b) => a + b, 0);
                    document.getElementById('stat-games').textContent = games.length;
                    document.getElementById('stat-news').textContent = news.length;
                    document.getElementById('stat-likes').textContent = totalLikes;
                    document.getElementById('stat-views').textContent = totalViews;
                    document.getElementById('stat-messages').textContent = messages.length;
                });
            }

            function renderAdminPanel() {
                updateAdminStats();
                renderAdminGames();
                document.querySelectorAll('.admin-tab').forEach(tab => {
                    tab.onclick = () => {
                        document.querySelectorAll('.admin-tab').forEach(t => t.classList.remove('active'));
                        tab.classList.add('active');
                        const tabName = tab.dataset.tab;
                        if (tabName === 'games') renderAdminGames();
                        else if (tabName === 'news') renderAdminNews();
                        else if (tabName === 'tutorials') renderAdminTutorials();
                        else if (tabName === 'faq') renderAdminFAQ();
                        else if (tabName === 'chatbot') renderAdminChatbot();
                        else if (tabName === 'messages') renderAdminMessages();
                        else if (tabName === 'ads') renderAdminAds();
                        else if (tabName === 'dashboard') renderAdminDashboard();
                        else if (tabName === 'users') renderAdminUsers();
                        else if (tabName === 'requests') renderAdminRequests();
                        else if (tabName === 'reports') renderAdminReports();
                        else if (tabName === 'releases') renderAdminReleases();
                        else if (tabName === 'activity') renderAdminActivity();
                        else if (tabName === 'settings') renderAdminSettings();
                    };
                });
            }

            async function renderAdminGames() {
                const content = document.getElementById('admin-content');
                const games = await getGames();
                content.innerHTML = `
                    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:var(--spacing-lg);flex-wrap:wrap;gap:var(--spacing-md);">
                        <h3>مدیریت بازی‌ها (${games.length})</h3>
                        <div style="display:flex;gap:var(--spacing-sm);flex-wrap:wrap;">
                            <button class="btn btn-primary btn-sm" onclick="window._addGame()">➕ افزودن بازی</button>
                            <button class="btn btn-sm" onclick="window._exportJSON()">📤 خروجی JSON</button>
                            <button class="btn btn-sm" onclick="window._importJSON()">📥 ورودی JSON</button>
                        </div>
                    </div>
                    ${games.length === 0 ? '<div class="empty-state"><div class="icon">🎮</div><h3>بازی‌ای ثبت نشده</h3></div>' : `
                    <div style="overflow-x:auto;">
                        <table class="admin-table">
                            <thead><tr><th>تصویر</th><th>عنوان</th><th>ژانر</th><th>سال</th><th>امتیاز</th><th>عملیات</th></tr></thead>
                            <tbody>
                                ${games.map(g => `
                                    <tr>
                                        <td>${g.imageData ? `<img src="${g.imageData}" />` : '🎮'}</td>
                                        <td>${g.title || '-'}</td>
                                        <td>${g.genre || '-'}</td>
                                        <td>${g.year || '-'}</td>
                                        <td>${getGameRating(g)}</td>
                                        <td>
                                            <button class="btn btn-sm" onclick="window._editGame('${g.id}')">✏️</button>
                                            <button class="btn btn-danger btn-sm" onclick="window._deleteGame('${g.id}')">🗑️</button>
                                        </td>
                                    </tr>
                                `).join('')}
                            </tbody>
                        </table>
                    </div>`}
                `;
            }

            window._addGame = function() { showGameForm(null); };
            window._editGame = function(id) { showGameForm(id); };
            window._deleteGame = async function(id) {
                const confirm = await showConfirm('آیا از حذف این بازی مطمئن هستید؟', 'حذف بازی', '🗑️');
                if (confirm) {
                    await dbDelete(STORES.games, id);
                    delete likes[id];
                    delete userRatings[id];
                    delete views[id];
                    localStorage.setItem('kraven_likes', JSON.stringify(likes));
                    localStorage.setItem('kraven_user_ratings', JSON.stringify(userRatings));
                    localStorage.setItem('kraven_views', JSON.stringify(views));
                    showToast('بازی حذف شد', 'success');
                    renderAdminGames();
                    updateAdminStats();
                    renderGames();
                    renderFeaturedSlider();
                }
            };

            function showGameForm(gameId) {
                const existingModal = document.getElementById('game-form-modal');
                if (existingModal) existingModal.remove();
                getGameById(gameId).then(game => {
                    const modal = document.createElement('div');
                    modal.id = 'game-form-modal';
                    modal.className = 'modal-overlay open';
                    modal.innerHTML = `
                        <div class="modal" style="max-width:700px;">
                            <h2>${gameId ? 'ویرایش بازی' : 'افزودن بازی جدید'}</h2>
                            <form id="game-form">
                                <div style="display:grid;grid-template-columns:1fr 1fr;gap:var(--spacing-md);">
                                    <div class="form-group"><label>عنوان بازی *</label><input type="text" id="gf-title" value="${game ? game.title || '' : ''}" required /></div>
                                    <div class="form-group"><label>ژانر *</label><input type="text" id="gf-genre" value="${game ? game.genre || '' : ''}" required /></div>
                                    <div class="form-group"><label>امتیاز</label><input type="text" id="gf-rating" value="${game ? game.rating || '' : ''}" placeholder="مثلاً 9.5" /></div>
                                    <div class="form-group"><label>سال انتشار</label><input type="text" id="gf-year" value="${game ? game.year || '' : ''}" placeholder="مثلاً 2024" /></div>
                                    <div class="form-group"><label>سازنده</label><input type="text" id="gf-developer" value="${game ? game.developer || '' : ''}" /></div>
                                    <div class="form-group"><label>حجم بازی</label><input type="text" id="gf-size" value="${game ? game.size || '' : ''}" placeholder="مثلاً 50GB" /></div>
                                    <div class="form-group">
                                        <label>پلتفرم</label>
                                        <select id="gf-platform">
                                            <option value="">انتخاب...</option>
                                            <option value="PC" ${game && game.platform === 'PC' ? 'selected' : ''}>PC</option>
                                            <option value="Mobile" ${game && game.platform === 'Mobile' ? 'selected' : ''}>Mobile</option>
                                            <option value="Console" ${game && game.platform === 'Console' ? 'selected' : ''}>Console</option>
                                            <option value="Multi-platform" ${game && game.platform === 'Multi-platform' ? 'selected' : ''}>Multi-platform</option>
                                        </select>
                                    </div>
                                    <div class="form-group">
                                        <label>حالت بازی</label>
                                        <select id="gf-mode">
                                            <option value="">انتخاب...</option>
                                            <option value="Singleplayer" ${game && game.mode === 'Singleplayer' ? 'selected' : ''}>تک‌نفره</option>
                                            <option value="Multiplayer" ${game && game.mode === 'Multiplayer' ? 'selected' : ''}>چندنفره</option>
                                            <option value="Both" ${game && game.mode === 'Both' ? 'selected' : ''}>هر دو</option>
                                        </select>
                                    </div>
                                    <div class="form-group">
                                        <label>وضعیت</label>
                                        <select id="gf-status">
                                            <option value="">انتخاب...</option>
                                            <option value="released" ${game && game.status === 'released' ? 'selected' : ''}>عرضه شده</option>
                                            <option value="coming_soon" ${game && game.status === 'coming_soon' ? 'selected' : ''}>به زودی</option>
                                        </select>
                                    </div>
                                    <div class="form-group" style="grid-column:1/-1;"><label>لینک‌های دانلود (هر خط یک لینک)</label><textarea id="gf-downloadLinks" rows="3">${game && game.downloadLinks ? game.downloadLinks.join('\n') : ''}</textarea></div>
                                    <div class="form-group">
                                        <label>عکس اصلی</label>
                                        <input type="file" id="gf-image" accept="image/*" />
                                        ${game && game.imageData ? `<img src="${game.imageData}" style="width:80px;height:50px;object-fit:cover;border-radius:10px;margin-top:4px;" />` : ''}
                                    </div>
                                    <div class="form-group"><label>گالری تصاویر</label><input type="file" id="gf-gallery" accept="image/*" multiple /></div>
                                    <div class="form-group" style="grid-column:1/-1;"><label>توضیح کوتاه</label><textarea id="gf-shortDesc" rows="3">${game ? game.shortDesc || '' : ''}</textarea></div>
                                    <div class="form-group" style="grid-column:1/-1;"><label>متن کامل</label><textarea id="gf-fullContent" rows="5">${game ? game.fullContent || '' : ''}</textarea></div>
                                    <div class="form-group" style="grid-column:1/-1;"><label>راهنمای نصب</label><textarea id="gf-installGuide" rows="4">${game ? game.installGuide || '' : ''}</textarea></div>
                                    <div class="form-group" style="grid-column:1/-1;"><label>حداقل سیستم</label><textarea id="gf-minRequirements" rows="4">${game ? game.minRequirements || '' : ''}</textarea></div>
                                    <div class="form-group" style="grid-column:1/-1;"><label>سیستم پیشنهادی</label><textarea id="gf-recRequirements" rows="4">${game ? game.recRequirements || '' : ''}</textarea></div>
                                </div>
                                <div class="modal-actions">
                                    <button type="button" class="btn" onclick="this.closest('.modal-overlay').remove()">انصراف</button>
                                    <button type="submit" class="btn btn-primary">${gameId ? 'ذخیره' : 'افزودن'}</button>
                                </div>
                            </form>
                        </div>
                    `;
                    document.body.appendChild(modal);
                    modal.querySelector('#game-form').addEventListener('submit', async (e) => {
                        e.preventDefault();
                        const title = document.getElementById('gf-title').value.trim();
                        const genre = document.getElementById('gf-genre').value.trim();
                        if (!title || !genre) { showToast('عنوان و ژانر الزامی است', 'error'); return; }
                        const downloadLinksText = document.getElementById('gf-downloadLinks').value.trim();
                        const downloadLinks = downloadLinksText ? downloadLinksText.split('\n').filter(l => l.trim()) : [];
                        const gameData = {
                            id: gameId || `game_${Date.now()}`,
                            title,
                            genre,
                            rating: document.getElementById('gf-rating').value.trim() || '0',
                            year: document.getElementById('gf-year').value.trim(),
                            developer: document.getElementById('gf-developer').value.trim(),
                            size: document.getElementById('gf-size').value.trim(),
                            platform: document.getElementById('gf-platform').value,
                            mode: document.getElementById('gf-mode').value,
                            status: document.getElementById('gf-status').value,
                            downloadLinks,
                            shortDesc: document.getElementById('gf-shortDesc').value.trim(),
                            fullContent: document.getElementById('gf-fullContent').value.trim(),
                            installGuide: document.getElementById('gf-installGuide').value.trim(),
                            minRequirements: document.getElementById('gf-minRequirements').value.trim(),
                            recRequirements: document.getElementById('gf-recRequirements').value.trim(),
                            likes: game ? (game.likes || 0) : 0,
                            userRatings: game ? (game.userRatings || []) : [],
                            createdAt: game ? (game.createdAt || new Date().toISOString()) : new Date().toISOString()
                        };
                        if (game) { gameData.imageData = game.imageData || ''; gameData.gallery = game.gallery || []; }
                        else { gameData.imageData = ''; gameData.gallery = []; }
                        const imageFile = document.getElementById('gf-image').files[0];
                        if (imageFile) gameData.imageData = await fileToBase64(imageFile);
                        const galleryFiles = document.getElementById('gf-gallery').files;
                        if (galleryFiles.length > 0) {
                            gameData.gallery = [];
                            for (let f of galleryFiles) gameData.gallery.push(await fileToBase64(f));
                        }
                        await dbPut(STORES.games, gameData);
                        showToast(gameId ? 'بازی ویرایش شد' : 'بازی اضافه شد', 'success');
                        modal.remove();
                        renderAdminGames();
                        renderGames();
                        renderFeaturedSlider();
                        updateAdminStats();
                    });
                });
            }

            function fileToBase64(file) {
                return new Promise((resolve, reject) => {
                    const reader = new FileReader();
                    reader.onload = () => resolve(reader.result);
                    reader.onerror = reject;
                    reader.readAsDataURL(file);
                });
            }

