/* ===== kraven-v2.js ===== */
/* KRAVEN GAME V2 — UX/performance enhancement layer */
(function(){
  'use strict';

  const ready = (fn) => {
    if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', fn, {once:true});
    else fn();
  };

  function injectRibbon(){
    const home=document.getElementById('page-home');
    const header=home && home.querySelector('.page-header');
    if(!header || document.getElementById('v2-command-ribbon')) return;
    const ribbon=document.createElement('div');
    ribbon.id='v2-command-ribbon';
    ribbon.innerHTML=[
      '<span class="v2-ribbon-item">⚡ <b>Discovery</b> سریع و هوشمند</span>',
      '<span class="v2-ribbon-item">🎮 <b>Games</b> بازی‌های قابل جستجو</span>',
      '<span class="v2-ribbon-item">📰 <b>News</b> اخبار و محتوای تازه</span>',
      '<span class="v2-ribbon-item">📱 <b>Responsive</b> دسکتاپ تا موبایل</span>'
    ].join('');
    header.insertAdjacentElement('afterend', ribbon);
  }

  function reveal(){
    const targets=document.querySelectorAll(
      '.game-card,.news-card,.stat-card,.achv-card,.comment-item,.calendar-item,.request-card'
    );
    if(!targets.length) return;
    if(!('IntersectionObserver' in window)){
      targets.forEach(el=>el.classList.add('v2-visible'));
      return;
    }
    const io=new IntersectionObserver((entries)=>{
      entries.forEach(entry=>{
        if(entry.isIntersecting){
          entry.target.classList.add('v2-visible');
          io.unobserve(entry.target);
        }
      });
    },{rootMargin:'0px 0px -8% 0px',threshold:.05});
    targets.forEach((el,i)=>{
      if(!el.classList.contains('v2-reveal')){
        el.classList.add('v2-reveal');
        el.style.transitionDelay=Math.min(i%8,7)*35+'ms';
      }
      io.observe(el);
    });
  }

  function lazyImages(){
    document.querySelectorAll('img:not([loading])').forEach(img=>{
      img.setAttribute('loading','lazy');
      img.setAttribute('decoding','async');
    });
  }

  function imageFallbacks(){
    document.addEventListener('error',function(e){
      const img=e.target;
      if(!img || img.tagName!=='IMG' || img.dataset.v2Fallback) return;
      img.dataset.v2Fallback='1';
      img.style.background='linear-gradient(135deg,#171923,#0d0e14)';
      img.style.objectFit='cover';
      img.removeAttribute('srcset');
      img.src='data:image/svg+xml;charset=UTF-8,'+encodeURIComponent(
        '<svg xmlns="http://www.w3.org/2000/svg" width="800" height="450" viewBox="0 0 800 450">'+
        '<defs><linearGradient id="g" x1="0" x2="1"><stop stop-color="#181a26"/><stop offset="1" stop-color="#0b0c12"/></linearGradient></defs>'+
        '<rect width="800" height="450" fill="url(#g)"/>'+
        '<text x="400" y="225" text-anchor="middle" fill="#9da3b5" font-family="sans-serif" font-size="30">KRAVEN GAME</text>'+
        '</svg>'
      );
    },true);
  }

  function keyboard(){
    document.addEventListener('keydown',function(e){
      const tag=(e.target && e.target.tagName || '').toLowerCase();
      const typing=tag==='input'||tag==='textarea'||tag==='select'||e.target?.isContentEditable;
      if(e.key==='/' && !typing){
        e.preventDefault();
        const btn=document.getElementById('global-search-btn');
        if(btn) btn.click();
      }
      if(e.key==='Escape'){
        document.body.classList.remove('v2-focus-mode');
      }
    });
  }

  function activeNav(){
    const links=document.querySelectorAll('.sidebar-nav a[data-page]');
    if(!links.length) return;
    const mark=()=>{
      const active=document.querySelector('.page.active');
      if(!active) return;
      const id=active.id.replace(/^page-/,'');
      links.forEach(a=>a.classList.toggle('active',a.dataset.page===id));
    };
    mark();
    const mo=new MutationObserver(mark);
    document.querySelectorAll('.page').forEach(p=>mo.observe(p,{attributes:true,attributeFilter:['class']}));
  }

  function performanceObserver(){
    if(!('PerformanceObserver' in window)) return;
    try{
      const po=new PerformanceObserver(list=>{
        list.getEntries().forEach(entry=>{
          if(entry.duration>1200) console.debug('[Kraven V2] slow resource:',entry.name,Math.round(entry.duration)+'ms');
        });
      });
      po.observe({type:'resource',buffered:true});
    }catch(_){}
  }

  function mutationEnhance(){
    const root=document.querySelector('main');
    if(!root || !('MutationObserver' in window)) return;
    let timer=0;
    const mo=new MutationObserver(()=>{
      clearTimeout(timer);
      timer=setTimeout(()=>{
        lazyImages();
        reveal();
      },120);
    });
    mo.observe(root,{childList:true,subtree:true});
  }

  ready(()=>{
    injectRibbon();
    lazyImages();
    imageFallbacks();
    keyboard();
    activeNav();
    performanceObserver();
    reveal();
    mutationEnhance();
    setTimeout(()=>{injectRibbon();lazyImages();reveal();},1200);
  });
})();

/* ===== kraven-v4.js ===== */
/* KRAVEN GAME V3 — interaction/polish layer */
(function(){
  'use strict';
  const ready=fn=>document.readyState==='loading'?document.addEventListener('DOMContentLoaded',fn,{once:true}):fn();

  function ribbon(){
    const home=document.getElementById('page-home');
    const header=home&&home.querySelector('.page-header');
    if(!header||document.getElementById('v3-command-ribbon')) return;
    const el=document.createElement('div');
    el.id='v3-command-ribbon';
    el.innerHTML=[
      '<div class="v3-ribbon-item">✦ <b>Premium UI</b><br>طراحی یکپارچه و مدرن</div>',
      '<div class="v3-ribbon-item">⚡ <b>Fast</b><br>تعامل سریع و روان</div>',
      '<div class="v3-ribbon-item">🎮 <b>Game Hub</b><br>کشف، جستجو و فیلتر بازی‌ها</div>',
      '<div class="v3-ribbon-item">◎ <b>Responsive</b><br>تجربه هماهنگ روی همه نمایشگرها</div>'
    ].join('');
    header.insertAdjacentElement('afterend',el);
  }

  function addTooltips(){
    document.querySelectorAll('.icon-btn[title],button[title],[aria-label]').forEach(el=>{
      if(!el.getAttribute('aria-label')&&el.getAttribute('title')) el.setAttribute('aria-label',el.getAttribute('title'));
    });
  }

  function navKeyboard(){
    document.addEventListener('keydown',e=>{
      if(e.key==='Escape') document.querySelectorAll('.modal-overlay.active,.search-overlay.active').forEach(x=>x.classList.remove('active'));
    });
  }

  function softScrollTop(){
    let last=0;
    window.addEventListener('scroll',()=>{
      const y=window.scrollY||0;
      const header=document.getElementById('main-header');
      if(header) header.classList.toggle('scrolled',y>28);
      const now=Date.now();
      if(now-last>120){
        document.documentElement.style.setProperty('--v3-scroll-progress',Math.min(100,(y/(document.documentElement.scrollHeight-innerHeight||1))*100)+'%');
        last=now;
      }
    },{passive:true});
  }

  function observeDynamic(){
    const root=document.querySelector('main');
    if(!root||!('MutationObserver' in window)) return;
    let t=0;
    new MutationObserver(()=>{
      clearTimeout(t);
      t=setTimeout(()=>{ribbon();addTooltips();},160);
    }).observe(root,{subtree:true,childList:true});
  }

  ready(()=>{ribbon();addTooltips();navKeyboard();softScrollTop();observeDynamic();setTimeout(ribbon,900);});
})();

/* ===== kraven-v5.js ===== */
(function(){
'use strict';
const DB='KravenGameDB', STORE={games:'games',users:'users',reviews:'reviews',comments:'comments',bookmarks:'bookmarks',notifications:'notifications',viewEvents:'viewEvents',releases:'releases'};
let db;
function openDB(){return new Promise((res,rej)=>{const r=indexedDB.open(DB,5);r.onsuccess=()=>{db=r.result;res(db)};r.onerror=()=>rej(r.error)})}
function all(store){return new Promise((res,rej)=>{if(!db)return res([]);const q=db.transaction(store,'readonly').objectStore(store).getAll();q.onsuccess=()=>res(q.result||[]);q.onerror=()=>rej(q.error)})}
function session(){return localStorage.getItem('kraven_session')}
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
function card(img,title,sub,score,id){return `<div class="v5-item" onclick="window._navigateToGame&&window._navigateToGame('${esc(id)}')"><img src="${esc(img||'')}" alt="" loading="lazy"><div><div class="t">${esc(title)}</div><div class="s">${esc(sub||'')}</div></div><div class="v5-score">${score??'—'}</div></div>`}
async function buildHome(){
  const home=document.getElementById('page-home'); if(!home||document.getElementById('v5-home-suite'))return;
  const suite=document.createElement('section');suite.id='v5-home-suite';suite.setAttribute('aria-label','Kraven Game V5 dashboard');
  suite.innerHTML='<div class="v5-panel wide" id="v5-trending-panel"><h3>🔥 Trending Now</h3><p>محبوب‌ترین بازی‌ها بر اساس امتیاز، لایک و فعالیت اخیر</p><div class="v5-list" id="v5-trending"></div></div><div class="v5-panel" id="v5-profile-panel"><h3>👤 Kraven Profile</h3><p>سطح، XP، دستاورد و فعالیت شما</p><div id="v5-profile-mini"></div></div><div class="v5-panel" id="v5-recommend-panel"><h3>🎯 Because You Liked...</h3><p>پیشنهادهای شخصی بر اساس علاقه‌مندی‌ها</p><div class="v5-list" id="v5-recommend"></div></div><div class="v5-panel full" id="v5-release-panel"><h3>🆕 Release Radar</h3><p>نسخه‌ها و عرضه‌های اخیر که ارزش دنبال‌کردن دارند</p><div class="v5-list" id="v5-releases"></div></div>';
  const featured=document.getElementById('featured-slider'); featured?.after(suite);
  await refreshHome();
}
async function refreshHome(){
  try{await openDB();const games=await all(STORE.games);const reviews=await all(STORE.reviews);const events=await all(STORE.viewEvents);const bms=await all(STORE.bookmarks);const users=await all(STORE.users);const releases=await all(STORE.releases);
    const now=Date.now(), week=7*864e5;
    const reviewStats=new Map(), recentViews=new Map();
    for(const r of reviews){const id=r.gameId;const x=reviewStats.get(id)||{sum:0,count:0};x.sum+=(+r.rating||0);x.count++;reviewStats.set(id,x);}
    for(const e of events){const ts=new Date(e.ts||0).getTime();if(now-ts<week){const id=e.gameId;recentViews.set(id,(recentViews.get(id)||0)+1);}}
    const score=g=>{const x=reviewStats.get(g.id);const avg=x&&x.count?x.sum/x.count:(+g.rating||0);return avg*2+(recentViews.get(g.id)||0)*0.18+(+g.likes||0)*0.04};
    const top=[...games].sort((a,b)=>score(b)-score(a)).slice(0,5);
    const t=document.getElementById('v5-trending'); if(t)t.innerHTML=top.map(g=>card(g.imageData,g.title,g.genre,'★ '+(g.rating||'0.0'),g.id)).join('')||'<div class="v5-item">اطلاعات کافی برای Trending هنوز جمع نشده.</div>';
    const sid=session(),u=users.find(x=>x.id===sid);const p=document.getElementById('v5-profile-mini'); if(p){if(!u){p.innerHTML='<div class="v5-hero-note"><div><strong>وارد شوید و Kraven را شخصی کنید</strong><br><span>Wishlist، XP، نقدها، اعلان‌ها و پیشنهادهای اختصاصی</span></div><button class="v5-pill primary" onclick="window._openAuth&&window._openAuth()">ورود</button></div>'}else{const xp=+u.xp||0,lvl=1+([0,100,250,500,1000,2000,3500,5500,8000,12000].filter(x=>xp>=x).length-1);const next=[100,250,500,1000,2000,3500,5500,8000,12000,16000][Math.min(lvl-1,9)];const prev=[0,100,250,500,1000,2000,3500,5500,8000,12000][Math.min(lvl-1,9)];const pct=Math.max(0,Math.min(100,((xp-prev)/Math.max(1,next-prev))*100));p.innerHTML=`<div class="v5-stat-grid"><div class="v5-stat"><div class="n">Lv ${lvl}</div><div class="l">سطح</div></div><div class="v5-stat"><div class="n">${xp}</div><div class="l">XP</div></div></div><div class="v5-progress"><span style="width:${pct}%"></span></div><div style="margin-top:9px;display:flex;justify-content:space-between;align-items:center"><span class="v5-badge">🏆 ${u.achievements?.length||0} achievements</span><button class="v5-pill" onclick="window._go&&window._go('profile')">پروفایل</button></div>`}}
    const liked=Object.keys(JSON.parse(localStorage.getItem('kraven_likes')||'{}')).filter(k=>JSON.parse(localStorage.getItem('kraven_likes')||'{}')[k]);let base=liked.map(id=>games.find(g=>g.id===id)).filter(Boolean);const genres=[...new Set(base.map(g=>g.genre).filter(Boolean))];let rec=games.filter(g=>!liked.includes(g.id)&&genres.includes(g.genre));if(!rec.length)rec=top.slice(0,4);document.getElementById('v5-recommend').innerHTML=rec.slice(0,4).map(g=>card(g.imageData,g.title,g.genre,'★ '+(g.rating||'0.0'),g.id)).join('')||'<div class="v5-item">هنوز پیشنهاد کافی نداریم.</div>';
    const rr=[...releases].sort((a,b)=>new Date(b.date||b.createdAt||0)-new Date(a.date||a.createdAt||0)).slice(0,5);document.getElementById('v5-releases').innerHTML=rr.map(r=>`<div class="v5-item"><div style="width:54px;height:40px;border-radius:9px;display:grid;place-items:center;background:linear-gradient(135deg,var(--accent),var(--accent3));font-size:1.1rem">🎮</div><div><div class="t">${esc(r.title||r.gameTitle||'Release')}</div><div class="s">${esc(r.version||r.date||'')}</div></div><div class="v5-score">${esc(r.platform||'')}</div></div>`).join('')||'<div class="v5-item">Release Radar هنوز داده‌ای ندارد.</div>';
  }catch(e){console.warn('Kraven V5 home layer:',e)}
}
function installBar(){if(document.getElementById('v5-appbar'))return;const h=document.getElementById('main-header');if(!h)return;const bar=document.createElement('div');bar.id='v5-appbar';bar.innerHTML='<button class="v5-pill primary" onclick="window._v5OpenProfile()">👤 پروفایل</button><button class="v5-pill" onclick="window._go&&window._go(\'compare\')">⚖️ مقایسه</button><button class="v5-pill" onclick="window._v5FocusSearch()">⌕ جستجوی سریع</button><button class="v5-pill" onclick="window._v5OpenStats()">📊 آمار Kraven</button><button class="v5-pill" onclick="window._v5Share()">↗ اشتراک‌گذاری</button>';h.after(bar)}
function drawer(id,title,body){let d=document.getElementById(id);if(d)d.remove();d=document.createElement('div');d.id=id;d.className='v5-drawer open';d.innerHTML=`<div class="v5-drawer-card"><div style="display:flex;justify-content:space-between;align-items:center;gap:10px"><h2 style="margin:0;font:900 1.15rem var(--font)">${title}</h2><button class="v5-pill" onclick="document.getElementById('${id}').remove()">✕</button></div>${body}</div>`;document.body.appendChild(d)}
window._v5OpenProfile=async function(){await openDB();const users=await all(STORE.users),u=users.find(x=>x.id===session());if(!u){window._openAuth&&window._openAuth();return}const reviews=await all(STORE.reviews),comments=await all(STORE.comments),bms=await all(STORE.bookmarks);drawer('v5-profile-drawer','پروفایل Kraven',`<div class="v5-stat-grid"><div class="v5-stat"><div class="n">Lv ${Math.max(1,[0,100,250,500,1000,2000,3500,5500,8000,12000].filter(x=>(u.xp||0)>=x).length)}</div><div class="l">Level</div></div><div class="v5-stat"><div class="n">${u.xp||0}</div><div class="l">XP</div></div><div class="v5-stat"><div class="n">${reviews.filter(x=>x.userId===u.id).length}</div><div class="l">Reviews</div></div><div class="v5-stat"><div class="n">${bms.filter(x=>x.userId===u.id).length}</div><div class="l">Bookmarks</div></div></div><h3 style="margin:18px 0 7px">🏆 Achievements</h3>${(u.achievements||[]).map(a=>`<div class="v5-ach"><div class="i">🏆</div><div><b>${esc(a)}</b><div style="font:.68rem var(--font);color:var(--text-muted)">Unlocked</div></div></div>`).join('')||'<div class="v5-ach locked"><div class="i">🔒</div><div>هنوز دستاوردی باز نشده</div></div>'}<h3 style="margin:18px 0 7px">💬 Community</h3><div class="v5-ach"><div>💬</div><div>${comments.filter(x=>x.userId===u.id).length} نظر ثبت‌شده</div></div>`)};
window._v5OpenStats=async function(){await openDB();const [g,n,u,r,c,e]=await Promise.all([all(STORE.games),all('news'),all(STORE.users),all(STORE.reviews),all(STORE.comments),all(STORE.viewEvents)]);drawer('v5-stats-drawer','Kraven Analytics',`<p>آمار محلی فعلی پروژه؛ برای آمار واقعی کل کاربران، Server API را اجرا کنید.</p><div class="v5-stat-grid"><div class="v5-stat"><div class="n">${g.length}</div><div class="l">Games</div></div><div class="v5-stat"><div class="n">${n.length}</div><div class="l">News</div></div><div class="v5-stat"><div class="n">${u.length}</div><div class="l">Users</div></div><div class="v5-stat"><div class="n">${r.length}</div><div class="l">Reviews</div></div><div class="v5-stat"><div class="n">${c.length}</div><div class="l">Comments</div></div><div class="v5-stat"><div class="n">${e.length}</div><div class="l">View Events</div></div></div>`)};
window._v5FocusSearch=function(){const b=document.getElementById('global-search-btn');if(b)b.click();else{const i=document.getElementById('search-input');i?.focus();i?.scrollIntoView({behavior:'smooth',block:'center'})}};
window._v5Share=function(){if(navigator.share)navigator.share({title:'Kraven Game',text:'Discover games on Kraven Game',url:location.href}).catch(()=>{});else navigator.clipboard?.writeText(location.href).then(()=>window.showToast&&window.showToast('لینک کپی شد','success'))};
function patchLogo(){const img=document.querySelector('#logo img');if(img){img.style.height=window.innerWidth<680?'50px':'64px';img.style.width='auto';img.style.maxWidth='none'}}
window.addEventListener('resize',patchLogo);document.addEventListener('DOMContentLoaded',async()=>{installBar();patchLogo();setTimeout(async()=>{await buildHome()},250);setTimeout(refreshHome,1800);});
let v5RefreshTimer=null;
function scheduleV5Refresh(delay=450){
  clearTimeout(v5RefreshTimer);
  if(document.getElementById('page-home')?.classList.contains('active')){
    v5RefreshTimer=setTimeout(()=>{v5RefreshTimer=null;refreshHome()},delay);
  }
}
window.addEventListener('hashchange',()=>scheduleV5Refresh(350));
window.addEventListener('kraven:navigate',()=>scheduleV5Refresh(350));
})();

/* ===== kraven-v6.js ===== */
/* KRAVEN GAME V6 — safe additive layer over the complete V5 build. */
(function(){
  'use strict';
  function el(id){return document.getElementById(id)}
  function safeClick(fn){try{fn&&fn()}catch(e){console.warn('Kraven V6 action:',e)}}
  function buildCommandCenter(){
    const sidebar=el('sidebar-menu'), nav=sidebar?.querySelector('.sidebar-nav');
    if(!sidebar||!nav||el('v6-command'))return;
    const box=document.createElement('div');
    box.id='v6-command'; box.className='v6-command';
    box.innerHTML=`
      <div class="v6-command-top">
        <div><div class="v6-command-title">KRAVEN COMMAND CENTER</div><div class="v6-command-sub">قابلیت‌های V5، حالا داخل منوی همبرگری</div></div>
        <span class="v6-live">READY</span>
      </div>
      <div class="v6-command-grid">
        <button type="button" class="v6-action primary" data-v6="profile"><span class="v6-ico">👤</span><span class="v6-copy">پروفایل<small>Level · XP · Achievements</small></span></button>
        <button type="button" class="v6-action" data-v6="compare"><span class="v6-ico">⚖️</span><span class="v6-copy">مقایسه بازی‌ها<small>Game Compare</small></span></button>
        <button type="button" class="v6-action" data-v6="search"><span class="v6-ico">⌕</span><span class="v6-copy">جستجوی سریع<small>Global Search</small></span></button>
        <button type="button" class="v6-action" data-v6="stats"><span class="v6-ico">📊</span><span class="v6-copy">آمار Kraven<small>Analytics</small></span></button>
        <button type="button" class="v6-action" data-v6="release"><span class="v6-ico">🆕</span><span class="v6-copy">Release Radar<small>عرضه‌های اخیر</small></span></button>
        <button type="button" class="v6-action" data-v6="share"><span class="v6-ico">↗</span><span class="v6-copy">اشتراک‌گذاری<small>Share Kraven</small></span></button>
      </div>`;
    sidebar.insertBefore(box,nav);
    const user=document.createElement('div'); user.id='v6-user-mini'; user.className='v6-user-mini';
    user.innerHTML='<div class="v6-user-dot">👤</div><div class="v6-user-text"><b id="v6-user-name">مهمان</b><span id="v6-user-status">برای امکانات بیشتر وارد شوید</span></div>';
    box.after(user);
    box.querySelectorAll('[data-v6]').forEach(btn=>btn.addEventListener('click',()=>{
      const action=btn.dataset.v6;
      safeClick(()=>{
        if(action==='profile') return window._v5OpenProfile?.();
        if(action==='compare') return window._go?.('compare');
        if(action==='search') return window._v5FocusSearch?.();
        if(action==='stats') return window._v5OpenStats?.();
        if(action==='share') return window._v5Share?.();
        if(action==='release') return window._go?.('calendar');
      });
      safeClick(()=>{ if(action!=='stats' && action!=='profile') document.getElementById('sidebar-close')?.click(); });
    }));
  }
  function syncUser(){
    const wrap=el('v6-user-mini'), name=el('v6-user-name'), status=el('v6-user-status');
    if(!wrap||!name||!status)return;
    try{
      const session=localStorage.getItem('kraven_session');
      if(!session){wrap.classList.remove('active');return}
      wrap.classList.add('active');
      name.textContent=(el('user-badge-btn')?.textContent||'کاربر Kraven').trim()||'کاربر Kraven';
      status.textContent='پروفایل · بوکمارک · Achievement';
    }catch(_){wrap.classList.remove('active')}
  }
  function init(){buildCommandCenter();syncUser()}
  document.addEventListener('DOMContentLoaded',()=>setTimeout(init,450));
  window.addEventListener('load',()=>setTimeout(init,900));
})();

/* ===== kraven-v7.js ===== */
/* KRAVEN GAME V7 — Gaming Platform Experience
   Additive layer on top of the stable V6 FIXED build.
   Uses existing V5/V6 data/navigation when available and localStorage for lightweight personalization.
*/
(function(){
  'use strict';
  const KEY='kraven_v7_state';
  const getState=()=>{try{return Object.assign({xp:0,quests:{},activity:[],theme:'default',recent:[]},JSON.parse(localStorage.getItem(KEY)||'{}'))}catch(_){return {xp:0,quests:{},activity:[],theme:'default',recent:[]}}};
  const saveState=s=>{try{localStorage.setItem(KEY,JSON.stringify(s))}catch(_){}};
  const esc=s=>{const d=document.createElement('div');d.textContent=s??'';return d.innerHTML};
  const $=s=>document.querySelector(s); const byId=id=>document.getElementById(id);
  const toast=(m,t='success')=>{try{window.showToast?window.showToast(m,t):console.log(m)}catch(_) {}};
  async function games(){try{if(typeof window.getGames==='function'){const a=await window.getGames();return Array.isArray(a)?a:[]}}catch(_){} return Array.from(document.querySelectorAll('.game-card')).map((c,i)=>({id:String(i),title:c.querySelector('.game-card-title')?.textContent?.trim()||'Game',rating:4.5}));}
  function openDialog(title,html){const o=byId('v7-overlay'); if(!o)return; o.querySelector('.v7-dialog-head h2').textContent=title; o.querySelector('.v7-dialog-body').innerHTML=html; o.classList.add('open'); document.body.classList.add('v7-lock');}
  function closeDialog(){byId('v7-overlay')?.classList.remove('open');document.body.classList.remove('v7-lock')}
  function go(page){try{window._go?.(page)}catch(_){}}
  function navigateGame(id){try{window._navigateToGame?.(id)}catch(_){}}
  function addActivity(text,ico='✨'){const s=getState();s.activity=[{text,ico,ts:Date.now()},...(s.activity||[])].slice(0,8);saveState(s);renderHub();}
  function quest(id,label,sub,xp,done){return `<div class="v7-quest ${done?'done':''}"><div class="v7-quest-main"><b>${done?'✅ ':''}${label}</b><span>${sub}</span></div><div class="v7-xp">+${xp} XP</div></div>`}
  function topGame(gs){return [...gs].sort((a,b)=>(Number(b.rating)||0)-(Number(a.rating)||0))[0]||{title:'Kraven Game',rating:4.8};}
  function gameName(g){return g?.title||g?.name||'بازی جدید'}
  function renderHub(){
    const home=document.querySelector('[data-page="home"]'); if(!home)return;
    const main=document.querySelector('main')||document.body; if(!main)return;
    let hub=byId('v7-hub'); if(!hub){hub=document.createElement('section');hub.id='v7-hub';hub.className='v7-hub v7-only';
      const target=document.querySelector('.page-header')||document.querySelector('#home-page')||main.firstElementChild; (target?.parentNode||main).insertBefore(hub,target?.nextSibling||main.firstChild);
    }
    games().then(gs=>{
      const featured=topGame(gs), s=getState(), doneCount=Object.values(s.quests||{}).filter(Boolean).length;
      const activities=(s.activity||[]).length?s.activity:[{text:'شروع تجربه Kraven V7',ico:'🚀'},{text:'به‌زودی پیشنهادهای شخصی‌تر فعال می‌شوند',ico:'🧠'}];
      const rec=gs.slice().sort((a,b)=>(Number(b.rating)||0)-(Number(a.rating)||0)).slice(0,4);
      hub.innerHTML=`<div class="v7-hub-shell">
        <div class="v7-hub-head"><div><div class="v7-kicker">KRAVEN V7 · DISCOVERY PLATFORM</div><div class="v7-title">مرکز کشف بازی‌ها</div><div class="v7-sub">پیشنهادها، کالکشن‌ها، مأموریت‌ها و فعالیت‌های تو؛ در یک داشبورد.</div><div class="v7-brand-strip"><span>🎮 Game Discovery</span><span>🏆 XP & Achievements</span><span>❤️ Wishlist</span><span>📰 News</span><span>🎬 Media</span></div></div><div class="v7-head-actions"><button class="v7-pill" data-v7="discover">🎯 کشف بازی</button><button class="v7-pill" data-v7="compare">⚖️ مقایسه</button><button class="v7-pill" data-v7="settings">⚙️ شخصی‌سازی</button></div></div>
        <div class="v7-grid">
          <div class="v7-panel v7-hero"><div><div class="v7-kicker">KRAVEN PICK</div><h3 style="font-size:1.15rem;margin-top:7px">${esc(gameName(featured))}</h3><p>انتخاب پیشنهادی بر اساس امتیاز و داده‌های فعلی بازی‌ها.</p><div class="v7-hero-score"><div class="v7-score">${Number(featured.rating||4.8).toFixed(1)}</div><div><div class="v7-stars">★★★★★</div><div style="font-size:.55rem;color:var(--text-muted);margin-top:3px">Kraven Score</div></div></div><div class="v7-hero-tags"><span class="v7-tag">⭐ Top Rated</span><span class="v7-tag">🔥 Trending</span><span class="v7-tag">🎯 Recommended</span></div></div><div class="v7-cta-row"><button class="btn btn-primary btn-sm" data-v7-game="${esc(String(featured.id||''))}">مشاهده بازی</button><button class="btn btn-sm" data-v7="wishlist">❤️ افزودن به Wishlist</button></div></div>
          <div class="v7-panel"><h3>🧠 پیشنهاد برای تو</h3><p>بازی‌هایی که ارزش بررسی بیشتری دارند.</p><div class="v7-mini-grid">${rec.map(g=>`<div class="v7-mini-card" data-v7-game="${esc(String(g.id||''))}"><b>${esc(gameName(g))}</b><span>⭐ ${Number(g.rating||4.5).toFixed(1)} · ${esc(g.genre||'Gaming')}</span></div>`).join('')}</div></div>
          <div class="v7-panel"><h3>🎯 مأموریت‌های امروز</h3><p>${doneCount}/3 مأموریت انجام شده</p>${quest('visit','بخش کشف را باز کن','یک بازی جدید پیدا کن',10,!!s.quests.visit)}${quest('save','یک بازی ذخیره کن','Wishlist / Bookmark',15,!!s.quests.save)}${quest('review','به یک بازی امتیاز بده','Review & Rating',25,!!s.quests.review)}<div class="v7-progress"><i style="width:${Math.min(100,doneCount/3*100)}%"></i></div></div>
          <div class="v7-panel"><h3>📡 Activity Feed</h3><p>آخرین اتفاق‌های Kraven</p>${activities.slice(0,5).map(a=>`<div class="v7-activity"><div class="v7-activity-ico">${a.ico||'•'}</div><div><b>${esc(a.text)}</b><span>${new Date(a.ts||Date.now()).toLocaleDateString('fa-IR')}</span></div></div>`).join('')}</div>
          <div class="v7-panel"><h3>🏆 پیشرفت</h3><p>Level بر اساس XP محلی</p><div class="v7-hero-score"><div class="v7-score" style="font-size:1.6rem">${Math.max(1,Math.floor((s.xp||0)/100)+1)}</div><div><b style="font-size:.72rem">KRAVEN PLAYER</b><div style="font-size:.55rem;color:var(--text-muted)">${(s.xp||0).toLocaleString('fa-IR')} XP</div></div></div><div class="v7-progress"><i style="width:${Math.min(100,(s.xp||0)%100)}%"></i></div></div>
          <div class="v7-panel"><h3>📰 مرکز محتوا</h3><p>دسترسی سریع به تجربه‌های مختلف سایت.</p><div class="v7-cta-row"><button class="v7-pill" data-v7="news">📰 اخبار</button><button class="v7-pill" data-v7="media">🎬 Media Center</button><button class="v7-pill" data-v7="collections">📚 Collections</button><button class="v7-pill" data-v7="release">📅 Release Radar</button></div></div>
        </div>
        <div class="v7-collections"><div class="v7-collection" data-v7="collection" data-name="Open World"><b>🌍 Open World</b><span>دنیاهای بزرگ و آزاد</span><small>کشف مجموعه</small></div><div class="v7-collection" data-v7="collection" data-name="Story Masters"><b>🎭 Story Masters</b><span>بازی‌های داستان‌محور</span><small>کشف مجموعه</small></div><div class="v7-collection" data-v7="collection" data-name="Hidden Gems"><b>💎 Hidden Gems</b><span>بازی‌هایی که شاید ندیده باشی</span><small>کشف مجموعه</small></div></div>
      </div>`;
      bindHub();
    });
  }
  function bindHub(){
    document.querySelectorAll('#v7-hub [data-v7]').forEach(b=>b.onclick=()=>runAction(b.dataset.v7,b.dataset.name));
    document.querySelectorAll('#v7-hub [data-v7-game]').forEach(b=>b.onclick=()=>{const id=b.dataset.v7Game;const s=getState();s.quests.visit=true;s.xp=(s.xp||0)+(s.quests.visit?0:10);saveState(s);addActivity('بازی را بررسی کردی','🎮');navigateGame(id)});
  }
  function completeQuest(id,xp,label){const s=getState();if(s.quests[id])return; s.quests[id]=true;s.xp=(s.xp||0)+xp;saveState(s);addActivity(label,'🏆');toast(`${xp} XP دریافت کردی!`,'success');}
  function runAction(action,name){
    if(action==='discover'){completeQuest('visit',10,'بخش Discovery را باز کردی');const gsPromise=games();gsPromise.then(gs=>openDiscover(gs));return}
    if(action==='compare')return openCompare();
    if(action==='settings')return openSettings();
    if(action==='wishlist'){completeQuest('save',15,'Wishlist را فعال کردی');go('bookmarks');return}
    if(action==='news')return go('news');
    if(action==='release')return go('calendar');
    if(action==='media')return openMedia();
    if(action==='collections')return openCollections();
    if(action==='collection')return openCollections(name);
  }
  function openDiscover(gs){
    openDialog('🎯 Kraven Discovery',`<input id="v7-discover-search" class="v7-search" placeholder="اسم بازی، ژانر یا پلتفرم را جستجو کن..."/><div id="v7-discover-results" class="v7-result-grid"></div>`);
    const render=q=>{const x=gs.filter(g=>`${gameName(g)} ${g.genre||''} ${g.platform||''}`.toLowerCase().includes(q.toLowerCase())).slice(0,18);byId('v7-discover-results').innerHTML=x.map(g=>`<div class="v7-result" data-v7-game="${esc(String(g.id||''))}"><b>${esc(gameName(g))}</b><span>⭐ ${Number(g.rating||4.5).toFixed(1)} · ${esc(g.genre||'Gaming')}</span></div>`).join('')||'<div style="color:var(--text-muted);font-size:.7rem">نتیجه‌ای پیدا نشد.</div>';document.querySelectorAll('#v7-discover-results [data-v7-game]').forEach(b=>b.onclick=()=>navigateGame(b.dataset.v7Game));};
    byId('v7-discover-search').oninput=e=>render(e.target.value);render('');
  }
  function openCompare(){
    games().then(gs=>{
      const list=gs.slice(0,18);openDialog('⚖️ Compare Center',`<p style="font-size:.68rem;color:var(--text-muted)">دو بازی را انتخاب کن.</p><div class="v7-result-grid">${list.map(g=>`<div class="v7-result" data-compare-id="${esc(String(g.id||''))}" data-title="${esc(gameName(g))}"><b>${esc(gameName(g))}</b><span>⭐ ${Number(g.rating||4.5).toFixed(1)}</span></div>`).join('')}</div><div id="v7-compare-out" style="margin-top:14px"></div>`);
      const sel=[];document.querySelectorAll('[data-compare-id]').forEach(b=>b.onclick=()=>{const id=b.dataset.compareId;if(sel.includes(id)){sel.splice(sel.indexOf(id),1);b.style.outline='none'}else if(sel.length<2){sel.push(id);b.style.outline='2px solid var(--accent)'}if(sel.length===2){const a=gs.find(g=>String(g.id)===sel[0]),c=gs.find(g=>String(g.id)===sel[1]);byId('v7-compare-out').innerHTML=`<table class="v7-compare-table"><thead><tr><th>ویژگی</th><th>${esc(gameName(a))}</th><th>${esc(gameName(c))}</th></tr></thead><tbody><tr><td>امتیاز</td><td>${Number(a.rating||4.5).toFixed(1)}</td><td>${Number(c.rating||4.5).toFixed(1)}</td></tr><tr><td>ژانر</td><td>${esc(a.genre||'—')}</td><td>${esc(c.genre||'—')}</td></tr><tr><td>پلتفرم</td><td>${esc(a.platform||'PC')}</td><td>${esc(c.platform||'PC')}</td></tr><tr><td>سال</td><td>${esc(a.year||'—')}</td><td>${esc(c.year||'—')}</td></tr></tbody></table>`}});
    });
  }
  function openCollections(name){
    const items=[['🌍 Open World','دنیای بزرگ و آزادی عمل بالا'],['🎭 Story Masters','داستان‌محور و سینمایی'],['💎 Hidden Gems','بازی‌های کمتر دیده‌شده'],['⚔️ Action Zone','تمرکز روی اکشن و مبارزه'],['🧠 Strategy Lab','استراتژی و مدیریت'],['👥 Multiplayer Nights','بازی‌های چندنفره']];
    const title=name?`📚 ${name}`:'📚 Kraven Collections';
    openDialog(title,`<div class="v7-collections" style="padding:0;grid-template-columns:repeat(2,1fr)">${items.map(x=>`<div class="v7-collection"><b>${x[0]}</b><span>${x[1]}</span><small>Collection ready</small></div>`).join('')}</div>`);
  }
  function openMedia(){openDialog('🎬 Media Center',`<div class="v7-grid" style="padding:0;grid-template-columns:repeat(2,1fr)"><div class="v7-panel"><h3>🎬 Trailers</h3><p>مرکز تریلرهای بازی‌ها و محتوای ویدیویی.</p></div><div class="v7-panel"><h3>🖼️ Screenshots</h3><p>گالری تصاویر بازی‌ها در یک فضای واحد.</p></div><div class="v7-panel"><h3>🎨 Wallpapers</h3><p>مجموعه تصاویر پس‌زمینه و Artwork.</p></div><div class="v7-panel"><h3>📰 Editorial</h3><p>خبرها و مقالات مرتبط با بازی‌ها.</p></div></div>`)}
  function openSettings(){openDialog('⚙️ Kraven Personalization',`<div class="v7-settings"><div class="v7-theme-card" data-theme-choice="1"><i style="background:linear-gradient(135deg,#6c5ce7,#fd79a8)"></i><b>Neon Violet</b></div><div class="v7-theme-card" data-theme-choice="2"><i style="background:linear-gradient(135deg,#0984e3,#00cec9)"></i><b>Cyber Blue</b></div><div class="v7-theme-card" data-theme-choice="3"><i style="background:linear-gradient(135deg,#00b894,#74b9ff)"></i><b>Emerald</b></div><div class="v7-theme-card" data-theme-choice="4"><i style="background:linear-gradient(135deg,#e17055,#fdcb6e)"></i><b>Sunset</b></div></div><div style="margin-top:16px" class="v7-panel"><h3>🧠 Discovery Profile</h3><p>تمرکز پیشنهادی: بازی‌های با امتیاز بالاتر، تازه‌واردها، Hidden Gems و ژانرهای مورد علاقه.</p></div>`);document.querySelectorAll('[data-theme-choice]').forEach(b=>b.onclick=()=>{byId('theme-btn')?.click();closeDialog()});}
  function buildOverlay(){if(byId('v7-overlay'))return;const o=document.createElement('div');o.id='v7-overlay';o.className='v7-overlay';o.innerHTML='<div class="v7-dialog"><div class="v7-dialog-head"><h2>Kraven V7</h2><button class="v7-close" aria-label="بستن">✕</button></div><div class="v7-dialog-body"></div></div>';document.body.appendChild(o);o.addEventListener('click',e=>{if(e.target===o||e.target.closest('.v7-close'))closeDialog()});}
  function enhanceDrawer(){const sidebar=byId('sidebar-menu'),nav=sidebar?.querySelector('.sidebar-nav');if(!sidebar||!nav||byId('v7-drawer-extra'))return;const box=document.createElement('div');box.id='v7-drawer-extra';box.className='v7-drawer-extra';box.innerHTML='<div class="v7-drawer-title">KRAVEN V7 COMMAND CENTER</div><div class="v7-drawer-grid"><button class="v7-drawer-action" data-v7-drawer="discover">🎯 Discovery</button><button class="v7-drawer-action" data-v7-drawer="compare">⚖️ Compare</button><button class="v7-drawer-action" data-v7-drawer="profile">👤 Profile</button><button class="v7-drawer-action" data-v7-drawer="collections">📚 Collections</button><button class="v7-drawer-action" data-v7-drawer="media">🎬 Media Center</button><button class="v7-drawer-action" data-v7-drawer="settings">⚙️ Settings</button><button class="v7-drawer-action" data-v7-drawer="activity">📡 Activity</button><button class="v7-drawer-action" data-v7-drawer="achievements">🏆 Achievements</button></div>';sidebar.insertBefore(box,nav);box.querySelectorAll('[data-v7-drawer]').forEach(b=>b.onclick=()=>{document.getElementById('sidebar-close')?.click();const a=b.dataset.v7Drawer;if(a==='discover')runAction('discover');else if(a==='compare')openCompare();else if(a==='profile')go('profile');else if(a==='collections')openCollections();else if(a==='media')openMedia();else if(a==='settings')openSettings();else if(a==='activity')openActivity();else if(a==='achievements')openAchievements();});}
  function openActivity(){const s=getState();openDialog('📡 Activity Feed',`<div>${(s.activity||[]).map(a=>`<div class="v7-activity"><div class="v7-activity-ico">${a.ico||'•'}</div><div><b>${esc(a.text)}</b><span>${new Date(a.ts||Date.now()).toLocaleString('fa-IR')}</span></div></div>`).join('')||'<p>هنوز فعالیتی ثبت نشده.</p>'}</div>`)}
  function openAchievements(){const s=getState();const list=[['🥇 First Explorer',s.quests.visit,'اولین کشف'],['❤️ Collector',s.quests.save,'اولین ذخیره'],['⭐ Reviewer',s.quests.review,'اولین امتیازدهی'],['🚀 V7 Pioneer',(s.xp||0)>=50,'رسیدن به ۵۰ XP']];openDialog('🏆 Achievements',`<div class="v7-mini-grid">${list.map(a=>`<div class="v7-mini-card ${a[1]?'done':''}"><b>${a[1]?'✅':'⬜'} ${a[0]}</b><span>${a[2]}</span></div>`).join('')}</div>`)}
  function installObservers(){
    let last='';
    const check=()=>{
      const page=document.querySelector('.page.active')?.dataset?.page||location.hash||'';
      if(page===last)return;
      last=page;
      if(String(page).includes('home')||!page)setTimeout(renderHub,250);
    };
    check();
    window.addEventListener('hashchange',check,{passive:true});
    window.addEventListener('kraven:navigate',check,{passive:true});
}
  let initialized=false;
  function init(){if(initialized)return;initialized=true;buildOverlay();enhanceDrawer();renderHub();installObservers();}
  document.addEventListener('DOMContentLoaded',()=>setTimeout(init,500),{once:true});
  window.KRAVEN_V7={openDiscover,openCompare,openCollections,openMedia,openSettings};
})();

/* ===== kraven-v8.js ===== */
/* KRAVEN GAME V8 — Auth Bridge, API Health, UX Resilience */
(function(){
  'use strict';
  const API_BASE = (()=>{
    try{ if(location.protocol==='http:'||location.protocol==='https:') return location.origin; }catch(_){}
    return 'http://127.0.0.1:8787';
  })();
  const api = async (path, options={})=>{
    const controller=new AbortController(); const timer=setTimeout(()=>controller.abort(),7000);
    try{
      const headers=Object.assign({'Content-Type':'application/json'},options.headers||{});
      const res=await fetch(API_BASE+path,Object.assign({},options,{headers,signal:controller.signal}));
      let data={}; try{data=await res.json()}catch(_){data={}};
      if(!res.ok){const e=new Error(data.error||`HTTP ${res.status}`);e.status=res.status;throw e;}
      return data;
    }finally{clearTimeout(timer)}
  };
  window.KRAVEN_V8_API={base:API_BASE,api};
  function toast(msg,type){try{window.showToast?.(msg,type)}catch(_){} }
  function setApiBadge(online){
    let el=document.getElementById('v8-api-status'); if(!el){
      const form=document.getElementById('auth-form-register')||document.getElementById('auth-modal');
      if(!form)return; el=document.createElement('div');el.id='v8-api-status';el.className='v8-api-status';
      el.innerHTML='<i></i><span>بررسی سرویس...</span>'; form.appendChild(el);
    }
    el.classList.toggle('online',online); el.querySelector('span').textContent=online?'حساب آنلاین فعال است':'حالت محلی فعال است';
  }
  async function probe(){try{await api('/api/health');setApiBadge(true);return true}catch(_){setApiBadge(false);return false}}
  async function registerOnline(payload){
    return api('/api/auth/register',{method:'POST',body:JSON.stringify(payload)});
  }
  async function runLocalRegister(original){
    try{return await original()}catch(err){throw err}
  }
  function wireAuth(){
    if(typeof window._authSubmit!=='function'||window._kravenV8AuthWrapped)return;
    const original=window._authSubmit;
    window._authSubmit=async function(){
      const loginVisible=document.getElementById('auth-form-login')?.style.display!=='none';
      if(loginVisible)return original.apply(this,arguments);
      const errEl=document.getElementById('auth-error'); if(errEl)errEl.textContent='';
      const username=document.getElementById('auth-reg-username')?.value.trim()||'';
      const displayName=document.getElementById('auth-reg-display')?.value.trim()||username;
      const email=document.getElementById('auth-reg-email')?.value.trim().toLowerCase()||'';
      const password=document.getElementById('auth-reg-pass')?.value||'';
      if(!username||!email||!password)return original.apply(this,arguments);
      const button=document.querySelector('#auth-form-register button[type="submit"], #auth-form-register .btn-primary');
      const old=button?.innerHTML; if(button){button.disabled=true;button.innerHTML='ساخت حساب...';}
      try{
        const online=await probe();
        if(online){
          try{
            const out=await registerOnline({username,displayName,email,password});
            const u={id:out.user.id,username:out.user.username,displayName:out.user.displayName||displayName,email:out.user.email,role:out.user.role||'user',xp:Number(out.user.xp||0),avatar:'',achievements:[],createdAt:new Date().toISOString(),serverToken:out.token};
            try{ if(typeof dbPut==='function'&&typeof STORES!=='undefined') await dbPut(STORES.users,u); }catch(_){ }
            if(typeof setUserSession==='function') await setUserSession(u); else localStorage.setItem('kraven_session',u.id);
            localStorage.setItem('kraven_api_token',out.token);
            try{ if(typeof awardXP==='function') await awardXP('register'); }catch(_){ }
            window._closeAuth?.();
            toast('حساب با موفقیت ساخته شد! 🎉','success');
            return;
          }catch(e){
            const msg=e.status===409?'نام کاربری یا ایمیل قبلاً استفاده شده است':(e.message||'خطا در ثبت‌نام آنلاین');
            if(errEl)errEl.textContent=msg;
            return;
          }
        }
        await runLocalRegister(original);
      }catch(e){
        if(errEl)errEl.textContent='ثبت‌نام انجام نشد؛ سرویس محلی مرورگر را بررسی کنید.';
      }finally{if(button){button.disabled=false;button.innerHTML=old||'ثبت‌نام'}}
    };
    window._kravenV8AuthWrapped=true;
  }
  function observeAuth(){
    wireAuth();
    const target=document.getElementById('auth-modal')||document.getElementById('auth-form-register')||document.getElementById('auth-form-login');
    if(target && 'MutationObserver' in window){
      const obs=new MutationObserver(()=>wireAuth());
      obs.observe(target,{childList:true,subtree:true});
    }
    setTimeout(probe,1200);
  }
  function improveLogo(){
    document.querySelectorAll('#logo,#site-logo,.logo,.brand-logo,.header-logo').forEach(el=>{
      if(el.tagName==='IMG'){el.removeAttribute('width');el.style.width='auto';el.style.maxWidth='260px';el.style.height='auto'}
    });
  }
  document.addEventListener('DOMContentLoaded',()=>{improveLogo();setTimeout(observeAuth,250)});
  window.addEventListener('load',()=>{improveLogo();setTimeout(wireAuth,250)});
})();

/* ===== kraven-v9.js ===== */
/* KRAVEN GAME V9 — Performance Core + Responsive Runtime */
(function(){'use strict';const perf=window.KRAVEN_V9={version:'9.0'};const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>Array.from(r.querySelectorAll(s));
function enhanceImages(root=document){$$('img',root).forEach(img=>{if(!img.getAttribute('decoding'))img.setAttribute('decoding','async');if(!img.closest('header,#loading-screen,.logo,.game-detail-header')&&!img.loading)img.loading='lazy';});}
function mobile(){const m=matchMedia('(max-width:780px)').matches;document.documentElement.classList.toggle('kraven-mobile',m);document.body.classList.toggle('kraven-mobile',m)}
function logoKeys(){const l=$('#logo');if(!l||l.dataset.v9kbd)return;l.dataset.v9kbd='1';l.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&typeof window._go==='function'){e.preventDefault();window._go('home')}})}
function boot(){mobile();enhanceImages();logoKeys();const run=()=>{enhanceImages();$$('.game-card').slice(0,1).forEach(c=>c.classList.add('v9-near'))};if('requestIdleCallback'in window)requestIdleCallback(run,{timeout:700});else setTimeout(run,80);window.addEventListener('resize',mobile,{passive:true});perf.ready=performance.now()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();})();

/* ===== kraven-v10.js ===== */
/* KRAVEN GAME V10 — Platform Edition | local-only intelligence, no server DB */
(function(){'use strict';
const KEY='kraven_v10_state';
const defaults={xp:0,likes:0,views:0,reviews:0,bookmarks:0,achievements:[],quests:{},history:[],wishlist:[],bookmarks:[],collections:[],activity:[],theme:'1'};
let state=loadState();let gamesCache=null;let activePanel='hub';
const $=(s,r=document)=>r.querySelector(s), esc=s=>{const d=document.createElement('div');d.textContent=s??'';return d.innerHTML};
function loadState(){try{return {...defaults,...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{return {...defaults}}}
function save(){localStorage.setItem(KEY,JSON.stringify(state))}
function user(){try{return typeof PLATFORM_USER==='function'?PLATFORM_USER():null}catch{return null}}
function currentXP(){const u=user();return Number(u?.xp||state.xp||0)}
function level(xp){return Math.min(50,1+Math.floor(Math.max(0,xp)/250))}
function addXP(n,reason='activity'){state.xp=Math.max(0,(state.xp||0)+n);state.activity.unshift({type:'xp',reason,at:Date.now(),xp:n});state.activity=state.activity.slice(0,30);save()}
function notify(msg){let t=$('.k10-toast');if(!t){t=document.createElement('div');t.className='k10-toast';document.body.appendChild(t)}t.innerHTML='<i>⚡</i><span>'+esc(msg)+'</span>';requestAnimationFrame(()=>t.classList.add('show'));clearTimeout(t._tm);t._tm=setTimeout(()=>t.classList.remove('show'),2600)}
async function getAll(){if(gamesCache)return gamesCache;try{if(typeof getGames==='function'){gamesCache=await getGames();return gamesCache||[]}}catch{}return []}
function openDrawer(panel='hub'){const o=$('#k10-overlay');if(!o)return;o.classList.add('open');setPanel(panel)}
function closeDrawer(){$('#k10-overlay')?.classList.remove('open')}
function setPanel(panel){activePanel=panel;document.querySelectorAll('.k10-panel').forEach(x=>x.classList.toggle('active',x.dataset.panel===panel));document.querySelectorAll('[data-k10-panel]').forEach(x=>x.classList.toggle('active',x.dataset.k10Panel===panel))}
function injectDrawer(){if($('#k10-overlay'))return;const o=document.createElement('div');o.id='k10-overlay';o.className='k10-overlay';o.innerHTML=`<aside class="k10-drawer" role="dialog" aria-label="Kraven Command Center"><div class="k10-drawer-head"><div class="k10-brand"><div class="k10-brand-mark">K</div><div><b>KRAVEN COMMAND</b><small style="display:block;color:var(--text-secondary);font-size:.64rem">Platform Edition • V10</small></div></div><button class="icon-btn" data-k10-close aria-label="بستن">✕</button></div><div class="k10-panel active" data-panel="hub"><div class="k10-mini" style="margin-bottom:10px"><strong id="k10-user-name">مهمان Kraven</strong><small id="k10-user-meta">Level 1 • XP 0</small><div class="k10-progress"><i id="k10-user-progress" style="width:0%"></i></div></div><div class="k10-nav">${navBtn('🎯','Discovery','کشف بازی‌ها','discovery')}${navBtn('👤','Kraven ID','پروفایل و پیشرفت','profile')}${navBtn('🏆','Achievements','دستاوردها و Quests','achievements')}${navBtn('❤️','Wishlist','علاقه‌مندی‌ها','wishlist')}${navBtn('📚','Collections','کالکشن‌ها','collections')}${navBtn('⚖️','Compare','مقایسه','compare')}${navBtn('🎬','Media Center','تریلر و گالری','media')}${navBtn('🔔','Notifications','اعلان‌ها','notifications')}${navBtn('🎨','Themes','شخصی‌سازی','themes')}${navBtn('⚙️','Settings','تنظیمات تجربه','settings')}</div></div><div class="k10-panel" data-panel="discovery"><div class="k10-search"><input id="k10-search" placeholder="جستجوی بازی، ژانر یا سازنده…"><button class="btn btn-primary" data-k10-search>جستجو</button></div><div id="k10-results"></div></div><div class="k10-panel" data-panel="profile"><div id="k10-profile"></div></div><div class="k10-panel" data-panel="achievements"><div id="k10-achievements"></div></div><div class="k10-panel" data-panel="wishlist"><div id="k10-wishlist"></div></div><div class="k10-panel" data-panel="collections"><div id="k10-collections"></div></div><div class="k10-panel" data-panel="compare"><div style="display:grid;gap:9px"><p style="color:var(--text-secondary);font-size:.75rem">مقایسهٔ کامل نسخهٔ اصلی Kraven از همین بخش در دسترس است.</p><button class="btn btn-primary" data-k10-action="compare">⚖️ باز کردن Compare Center</button></div></div><div class="k10-panel" data-panel="media"><div id="k10-media"></div></div><div class="k10-panel" data-panel="notifications"><div id="k10-notifications"></div></div><div class="k10-panel" data-panel="themes"><div id="k10-themes"></div></div><div class="k10-panel" data-panel="settings"><div class="k10-grid" style="grid-template-columns:1fr"><button class="btn" data-k10-action="scrolltop">⬆️ رفتن به بالای صفحه</button><button class="btn" data-k10-action="home">🏠 بازگشت به خانه</button><button class="btn" data-k10-action="resetv10">♻️ ریست امکانات V10</button></div></div></aside>`;document.body.appendChild(o);o.addEventListener('click',e=>{if(e.target===o)e.currentTarget.classList.remove('open');const p=e.target.closest('[data-k10-panel]');if(p){e.preventDefault();setPanel(p.dataset.k10Panel);renderPanel(p.dataset.k10Panel)}if(e.target.closest('[data-k10-close]'))closeDrawer();const a=e.target.closest('[data-k10-action]');if(a)doAction(a.dataset.k10Action);if(e.target.closest('[data-k10-search]'))performSearch()});$('#k10-search')?.addEventListener('keydown',e=>{if(e.key==='Enter')performSearch()})}
function navBtn(i,title,sub,p){return `<button data-k10-panel="${p}"><span class="left"><span class="ico">${i}</span><span><b>${title}</b><small style="display:block;color:var(--text-secondary);font-size:.58rem">${sub}</small></span></span><span class="k10-chip">›</span></button>`}
function doAction(a){if(a==='compare'){try{closeDrawer();window._go?.('compare')}catch{}}else if(a==='scrolltop')window.scrollTo({top:0,behavior:'smooth'});else if(a==='home'){closeDrawer();window._go?.('home')}else if(a==='resetv10'){if(confirm('تنظیمات محلی V10 پاک شود؟')){localStorage.removeItem(KEY);state={...defaults};save();renderAll();notify('تنظیمات V10 ریست شد')}}}
function injectHome(){if($('#k10-home-sections'))return;const anchor=$('#games-section')||$('.page-header')?.parentElement;if(!anchor)return;const wrap=document.createElement('div');wrap.id='k10-home-sections';wrap.innerHTML=`<section class="k10-section"><div class="k10-section-head"><div><div class="k10-title">🔥 Kraven Trending</div><div class="k10-sub">بازی‌هایی که الان بیشتر مورد توجه‌اند</div></div><div class="k10-actions"><button class="k10-pill active" data-k10-home-tab="trending">محبوب</button><button class="k10-pill" data-k10-home-tab="rising">در حال رشد</button><button class="k10-pill" data-k10-home-tab="hidden">Hidden Gems</button></div></div><div class="k10-rail" id="k10-trending-rail"></div></section><section class="k10-section"><div class="k10-section-head"><div><div class="k10-title">🎯 Discovery Engine</div><div class="k10-sub">پیشنهادهای سبک‌وزن و محلی بر اساس علایق و فعالیت تو</div></div><button class="k10-pill" data-k10-open="discovery">باز کردن Discovery</button></div><div class="k10-grid" id="k10-discovery-grid"></div></section><section class="k10-section"><div class="k10-section-head"><div><div class="k10-title">🏆 Daily Quest</div><div class="k10-sub">هر روز یک قدم کوچک برای ساختن پروفایل Kraven</div></div><span class="k10-hot">⚡ XP محلی</span></div><div class="k10-grid" id="k10-quest-grid"></div></section><section class="k10-section"><div class="k10-section-head"><div><div class="k10-title">🎬 Kraven Media</div><div class="k10-sub">مرکز تریلر، اسکرین‌شات و محتوای رسانه‌ای</div></div><button class="k10-pill" data-k10-open="media">مشاهده همه</button></div><div class="k10-grid" id="k10-media-grid"></div></section></div>`;anchor.insertAdjacentElement('afterend',wrap);wrap.addEventListener('click',e=>{const op=e.target.closest('[data-k10-open]');if(op){openDrawer(op.dataset.k10Open);renderPanel(op.dataset.k10Open)}const tab=e.target.closest('[data-k10-home-tab]');if(tab){wrap.querySelectorAll('[data-k10-home-tab]').forEach(b=>b.classList.remove('active'));tab.classList.add('active');renderTrending(tab.dataset.k10HomeTab)}})}
function card(g,i){const img=g.imageData||g.image||'';const title=esc(g.title||'Unknown Game');return `<article class="k10-card" data-k10-game="${esc(String(g.id))}" tabindex="0"><span class="k10-rank">${i+1}</span>${g.badge?`<span class="k10-badge">${esc(g.badge)}</span>`:''}${img?`<img class="k10-thumb" src="${img}" alt="${title}" loading="lazy" decoding="async">`:`<div class="k10-thumb" style="display:grid;place-items:center;font-size:2rem">🎮</div>`}<div class="k10-body"><div class="k10-name">${title}</div><div class="k10-meta"><span>⭐ ${esc(String(g.rating||g.score||'—'))}</span><span>${esc(String(g.year||'—'))}</span></div></div></article>`}
async function renderTrending(mode='trending'){const el=$('#k10-trending-rail');if(!el)return;let gs=await getAll();if(!gs.length){el.innerHTML='<div class="k10-mini">دیتای بازی در دسترس نیست.</div>';return}const views=JSON.parse(localStorage.getItem('kraven_views')||'{}'),likes=JSON.parse(localStorage.getItem('kraven_likes')||'{}');let arr=[...gs];if(mode==='rising')arr.sort((a,b)=>(Number(views[b.id]||0)+Number(likes[b.id]||0)*5)-(Number(views[a.id]||0)+Number(likes[a.id]||0)*5));else if(mode==='hidden')arr.sort((a,b)=>Number((b.rating||b.score||0))-Number((a.rating||a.score||0)));else arr.sort((a,b)=>Number((b.rating||b.score||0))-Number((a.rating||a.score||0)));el.innerHTML=arr.slice(0,10).map((g,i)=>card(g,i)).join('');}
async function renderDiscovery(){const el=$('#k10-discovery-grid');if(!el)return;const gs=await getAll();const history=state.history||[];let picks=[...gs];const q=history.length?history.map(x=>x.genre).filter(Boolean):[];picks.sort((a,b)=>{const ag=q.includes(a.genre)?1:0,bg=q.includes(b.genre)?1:0;return bg-ag||Number((b.rating||b.score||0))-Number((a.rating||a.score||0))});el.innerHTML=picks.slice(0,4).map(g=>`<div class="k10-mini" data-k10-game="${esc(String(g.id))}"><strong>🎯 ${esc(g.title||'بازی')}</strong><small>${esc(g.genre||'Gaming')} • ${esc(String(g.year||'—'))}</small><div style="margin-top:8px;font-size:.64rem;color:var(--text-secondary)">پیشنهاد محلی بر اساس داده‌های مرورگر</div></div>`).join('')||'<div class="k10-mini">پیشنهادی پیدا نشد.</div>'}
function renderQuests(){const el=$('#k10-quest-grid');if(!el)return;const day=new Date().toISOString().slice(0,10);const done=state.quests?.[day]||{};const qs=[['discover','🔎','۳ بازی را باز کن',3,25,'views'],['bookmark','🔖','یک بازی را ذخیره کن',1,20,'bookmarks'],['wishlist','❤️','یک بازی به Wishlist اضافه کن',1,20,'wishlist']];el.innerHTML=qs.map(([id,ic,t,goal,xp,key])=>{const cur=done[id]||0;const pct=Math.min(100,Math.round(cur/goal*100));return `<div class="k10-mini"><strong>${ic} ${t}</strong><small>${cur}/${goal} • +${xp} XP</small><div class="k10-progress"><i style="width:${pct}%"></i></div><button class="k10-pill" style="margin-top:10px" data-k10-quest="${id}" data-k10-xp="${xp}">${pct>=100?'✓ تکمیل شد':'انجام بده'}</button></div>`}).join('')}
function renderMedia(){const el=$('#k10-media-grid');if(!el)return;el.innerHTML=`<div class="k10-mini"><strong>🎬 Trailers</strong><small>مرور سریع بازی‌های دارای محتوای رسانه‌ای</small><button class="k10-pill" style="margin-top:9px" data-k10-panel="media">باز کردن</button></div><div class="k10-mini"><strong>🖼️ Screenshots</strong><small>گالری‌های بازی از صفحهٔ اختصاصی</small><button class="k10-pill" style="margin-top:9px" data-k10-panel="media">گالری</button></div><div class="k10-mini"><strong>🎨 Wallpapers</strong><small>محل آماده برای والپیپرهای Kraven</small><button class="k10-pill" style="margin-top:9px" data-k10-panel="media">مشاهده</button></div><div class="k10-mini"><strong>📺 Media Center</strong><small>یک نقطهٔ دسترسی برای تمام Media</small><button class="k10-pill" style="margin-top:9px" data-k10-open="media">ورود</button></div>`}
function renderPanel(p){if(p==='discovery')performSearch(true);if(p==='profile')renderProfile();if(p==='achievements')renderAchievements();if(p==='wishlist')renderWishlist();if(p==='collections')renderCollections();if(p==='media')renderMediaPanel();if(p==='notifications')renderNotifications();if(p==='themes')renderThemes();updateUserMini()}
function updateUserMini(){const n=user()?.displayName||user()?.username||'مهمان Kraven';const xp=currentXP(),lv=level(xp),pct=((xp%250)/250)*100;$('#k10-user-name')&&( $('#k10-user-name').textContent=n);$('#k10-user-meta')&&($('#k10-user-meta').textContent=`Level ${lv} • XP ${xp}`);$('#k10-user-progress')&&($('#k10-user-progress').style.width=pct+'%')}
function renderProfile(){const el=$('#k10-profile');if(!el)return;const xp=currentXP(),lv=level(xp);el.innerHTML=`<div class="k10-mini"><strong>👤 Kraven ID</strong><small>${esc(user()?.displayName||user()?.username||'حساب محلی')}</small><div class="k10-progress"><i style="width:${(xp%250)/250*100}%"></i></div><div class="k10-meta" style="margin-top:9px"><span>Level ${lv}</span><span>${xp} XP</span></div></div><div class="k10-grid" style="margin-top:10px"><div class="k10-mini"><strong>${state.history?.length||0}</strong><small>History</small></div><div class="k10-mini"><strong>${state.wishlist?.length||0}</strong><small>Wishlist</small></div><div class="k10-mini"><strong>${state.bookmarks?.length||0}</strong><small>Bookmarks</small></div><div class="k10-mini"><strong>${state.achievements?.length||0}</strong><small>Achievements</small></div></div><div style="margin-top:12px;display:grid;gap:8px"><button class="btn btn-primary" data-k10-action="home">🏠 خانه</button></div>`}
function renderAchievements(){const el=$('#k10-achievements');if(!el)return;const defs=[['first_view','👀','اولین کشف','یک بازی را باز کن'],['explorer','🧭','Explorer','۱۰ بازی را باز کن'],['collector','📚','Collector','۵ بازی را ذخیره کن'],['rater','⭐','Rater','یک امتیاز ثبت کن'],['daily','🎯','Daily Player','یک Quest روزانه را کامل کن']];el.innerHTML=defs.map(d=>`<div class="k10-mini" style="margin-bottom:8px;opacity:${state.achievements.includes(d[0])?1:.62}"><strong>${d[1]} ${d[2]} ${state.achievements.includes(d[0])?'✓':''}</strong><small>${d[3]}</small></div>`).join('')}
function renderWishlist(){const el=$('#k10-wishlist');if(!el)return;const ids=state.wishlist||[];el.innerHTML=ids.length?ids.map(id=>`<div class="k10-mini" style="margin-bottom:8px"><strong>❤️ ${esc(String(id))}</strong><small>ذخیره‌شده در Wishlist محلی</small></div>`).join(''):'<div class="k10-mini">Wishlist هنوز خالی است.</div>'}
function renderCollections(){const el=$('#k10-collections');if(!el)return;const defs=[['🎯','Weekend Picks','بازی‌های پیشنهادی برای آخر هفته'],['🌌','Open World','دنیاهای باز و اکتشاف'],['💎','Hidden Gems','بازی‌های کم‌تر دیده‌شده']];el.innerHTML=defs.map(d=>`<div class="k10-mini" style="margin-bottom:8px"><strong>${d[0]} ${d[1]}</strong><small>${d[2]}</small><button class="k10-pill" style="margin-top:9px" data-k10-collection="${esc(d[1])}">باز کردن</button></div>`).join('')}
function renderMediaPanel(){const el=$('#k10-media');if(!el)return;el.innerHTML=`<div class="k10-mini"><strong>🎬 Media Center</strong><small>این مرکز به داده‌های موجود در صفحات بازی متصل می‌شود.</small></div><div class="k10-grid" style="margin-top:9px"><div class="k10-mini"><strong>🎬 Trailers</strong><small>تریلرهای مرتبط با بازی‌ها</small></div><div class="k10-mini"><strong>🖼️ Screenshots</strong><small>گالری تصاویر</small></div><div class="k10-mini"><strong>🎨 Wallpapers</strong><small>والپیپرها</small></div><div class="k10-mini"><strong>📺 Video Hub</strong><small>محتوای ویدیویی</small></div></div>`}
function renderNotifications(){const el=$('#k10-notifications');if(!el)return;const a=(state.activity||[]).slice(0,8);el.innerHTML=a.length?a.map(x=>`<div class="k10-mini" style="margin-bottom:8px"><strong>${x.type==='xp'?'⚡ XP':'📌 Activity'}</strong><small>${esc(x.reason||'فعالیت')} • ${new Date(x.at||Date.now()).toLocaleString('fa-IR')}</small></div>`).join(''):'<div class="k10-mini">اعلان جدیدی وجود ندارد.</div>'}
function renderThemes(){const el=$('#k10-themes');if(!el)return;el.innerHTML=`<div class="k10-grid"><button class="k10-mini" data-k10-theme="1"><strong>🟣 Neon Violet</strong><small>تم پیش‌فرض</small></button><button class="k10-mini" data-k10-theme="5"><strong>💗 Neon Pink</strong><small>انرژی بیشتر</small></button><button class="k10-mini" data-k10-theme="3"><strong>🟢 Emerald</strong><small>سبز نئونی</small></button><button class="k10-mini" data-k10-theme="9"><strong>⚫ AMOLED</strong><small>حداقل نور</small></button></div>`}
async function performSearch(silent=false){const inp=$('#k10-search');if(!inp)return;const q=inp.value.trim().toLowerCase();const out=$('#k10-results');if(!out)return;const gs=await getAll();let rs=gs;if(q)rs=gs.filter(g=>[g.title,g.genre,g.developer,g.publisher,g.shortDesc,g.fullContent,g.kravenMeta?.originalTitle].some(v=>String(v||'').toLowerCase().includes(q)));out.innerHTML=(rs.slice(0,20).map(g=>`<div class="k10-result" data-k10-game="${esc(String(g.id))}">${g.imageData?`<img src="${g.imageData}" loading="lazy" alt="">`:'<div style="width:56px;height:42px;border-radius:10px;background:#1a1d28;display:grid;place-items:center">🎮</div>'}<div><b>${esc(g.title||'بازی')}</b><span>${esc(g.genre||'')} • ${esc(String(g.year||''))}</span></div><span>›</span></div>`).join(''))||'<div class="k10-mini">نتیجه‌ای پیدا نشد.</div>';if(!silent&&q)notify(`${rs.length} نتیجه پیدا شد`)}
function openGame(id){state.history.unshift({id,genre:null,at:Date.now()});state.history=state.history.slice(0,50);state.views=(state.views||0)+1;if(!state.achievements.includes('first_view'))state.achievements.push('first_view');if(state.views>=10&&!state.achievements.includes('explorer'))state.achievements.push('explorer');addXP(1,'مشاهده بازی');save();try{closeDrawer();window._navigateToGame?.(id)}catch{}}
function bindGlobal(){document.addEventListener('click',e=>{const g=e.target.closest('[data-k10-game]');if(g){e.preventDefault();openGame(g.dataset.k10Game);return}const th=e.target.closest('[data-k10-theme]');if(th){const t=th.dataset.k10Theme;try{localStorage.setItem('kraven_theme',t);document.body.setAttribute('data-theme',t);if(typeof theme!=='undefined'){}notify('تم Kraven تغییر کرد')}catch{}return}const q=e.target.closest('[data-k10-quest]');if(q){const day=new Date().toISOString().slice(0,10);state.quests[day]=state.quests[day]||{};const id=q.dataset.k10Quest, done=state.quests[day][id]||0;if(id==='discover'&&done>=3||id!=='discover'&&done>=1){notify('این Quest تکمیل شده');return}state.quests[day][id]=done+(id==='discover'?1:1);if((id==='discover'&&state.quests[day][id]===3)||(id!=='discover'&&state.quests[day][id]===1)){addXP(Number(q.dataset.k10Xp||10),'Daily Quest');if(!state.achievements.includes('daily'))state.achievements.push('daily');notify('Quest کامل شد +XP')}save();renderQuests();return}const open=e.target.closest('[data-k10-open]');if(open){openDrawer(open.dataset.k10Open);renderPanel(open.dataset.k10Open)}} ,{passive:false});const hamburger=$('#hamburger-btn');hamburger?.addEventListener('click',e=>{e.preventDefault();openDrawer('hub')});window.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer();if(e.key==='/'&&!/input|textarea|select/i.test(e.target.tagName)){openDrawer('discovery');setTimeout(()=>$('#k10-search')?.focus(),50)}})}
function createBottomNav(){if($('.k10-bottom-nav'))return;const n=document.createElement('nav');n.className='k10-bottom-nav';n.setAttribute('aria-label','پیمایش موبایل');n.innerHTML=`<button data-k10-bottom="home" class="active"><span>🏠</span>خانه</button><button data-k10-bottom="discovery"><span>🔎</span>کشف</button><button data-k10-bottom="wishlist"><span>❤️</span>لیست</button><button data-k10-bottom="compare"><span>⚖️</span>مقایسه</button><button data-k10-bottom="hub"><span>☰</span>منو</button>`;document.body.appendChild(n);n.addEventListener('click',e=>{const b=e.target.closest('[data-k10-bottom]');if(!b)return;n.querySelectorAll('button').forEach(x=>x.classList.remove('active'));b.classList.add('active');const a=b.dataset.k10Bottom;if(a==='home')window._go?.('home');else if(a==='compare')window._go?.('compare');else{openDrawer(a);renderPanel(a)}})}
function performance(){const reduce=matchMedia('(prefers-reduced-motion:reduce)').matches;if(reduce)return;const io='IntersectionObserver'in window?new IntersectionObserver(es=>es.forEach(x=>{if(x.isIntersecting){x.target.style.contentVisibility='visible';io.unobserve(x.target)}}),{rootMargin:'200px'}):null;if(io)document.querySelectorAll('.k10-card,.k10-section').forEach(el=>io.observe(el));}
function seo(){const desc=document.querySelector('meta[name="description"]');if(desc)desc.setAttribute('content','Kraven Game — پلتفرم کشف بازی، اخبار، بررسی، مجموعه‌ها و تجربه گیمینگ فارسی.');let can=document.querySelector('link[rel="canonical"]');if(!can){can=document.createElement('link');can.rel='canonical';can.href=location.href.split('#')[0];document.head.appendChild(can)}}
async function boot(){injectDrawer();injectHome();createBottomNav();bindGlobal();seo();updateUserMini();renderTrending();renderDiscovery();renderQuests();renderMedia();performance();setTimeout(()=>document.documentElement.classList.add('kraven-v10-ready'),150)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
window.KRAVEN_V10={open:openDrawer,state,renderAll:()=>{renderTrending();renderDiscovery();renderQuests();renderMedia();updateUserMini()}};
})();

/* ===== kraven-admin-save.js ===== */
/* Kraven Game - Admin Save + welcome controls */
(function () {
  'use strict';
  function isAdmin() { return document.body.classList.contains('admin-mode'); }
  function inject() {
    const panel = document.querySelector('#page-admin .admin-panel');
    if (!panel) return;
    if (!panel.querySelector('#kraven-admin-welcome')) {
      const welcome = document.createElement('div');
      welcome.id = 'kraven-admin-welcome';
      welcome.innerHTML = `<strong>👑 خوش آمدید ادمین Kraven Game</strong><span>پنل مدیریت آماده است. تغییرات محتوا را می‌توانی دستی یا با Auto-Save ذخیره کنی.</span>`;
      panel.insertBefore(welcome, panel.firstChild);
    }
    if (panel.querySelector('#kraven-admin-save-bar')) return;
    const bar = document.createElement('div');
    bar.id = 'kraven-admin-save-bar';
    bar.innerHTML = `
      <div class="kas-copy"><strong>💾 ذخیره تغییرات</strong><span id="kas-status">تغییرات پنل را در فایل‌های پروژه منتشر کن.</span></div>
      <div class="kas-actions">
        <button type="button" class="btn btn-primary btn-sm" id="kas-save-now">💾 ذخیره تغییرات</button>
        <button type="button" class="btn btn-sm" id="kas-mark-save">⏱️ اتصال پوشه + Auto-Save</button>
      </div>`;
    panel.insertBefore(bar, panel.firstChild);
    const save = document.getElementById('kas-save-now');
    const mark = document.getElementById('kas-mark-save');
    const status = document.getElementById('kas-status');
    save.addEventListener('click', async () => {
      if (!window.KRAVEN_CONTENT_SYNC?.exportAll) { status.textContent = 'Content Engine در دسترس نیست.'; return; }
      status.textContent = 'در حال ذخیره...'; save.disabled = true;
      try {
        const ok = await window.KRAVEN_CONTENT_SYNC.exportAll();
        status.textContent = ok ? '✓ همه تغییرات در فایل‌های پروژه ذخیره شد.' : '⚠ ابتدا پوشه پروژه را متصل کن.';
      } catch (e) { status.textContent = '✕ ذخیره ناموفق بود.'; }
      save.disabled = false;
    });
    mark.addEventListener('click', () => window.KRAVEN_CONTENT_SYNC?.connectFolder?.());
  }
  document.addEventListener('DOMContentLoaded', () => {
    const observer = new MutationObserver(() => { if (isAdmin()) inject(); });
    observer.observe(document.body, { attributes: true, attributeFilter: ['class'] });
    setInterval(() => { if (isAdmin()) inject(); }, 1200);
  }, { once: true });
})();

/* ===== kraven-content-sync.js ===== */
/*
 * KRAVEN CONTENT ENGINE V13
 * Static publishing workflow for GitHub Pages.
 * - Website reads /data/*.json when published files exist.
 * - Admin can connect a local project folder (Chrome/Edge File System Access API).
 * - Changes are auto-exported 10 seconds after the last content mutation.
 * - Images stored as data URLs are written into assets/content/* and JSON stores relative paths.
 * - No database/server is required.
 */
(function(){
  'use strict';
  const ROOT = 'data';
  const ASSET_ROOT = 'assets/content';
  const AUTO_MS = 10000;
  const FILES = {
    games: 'games.json', news: 'news.json', tutorials: 'tutorials.json', faq: 'faq.json',
    ads: 'ads.json', adSlots: 'ad-slots.json', releases: 'releases.json'
  };
  const CONTENT_STORES = Object.keys(FILES);
  let dirHandle = null;
  let timer = null;
  let dirty = false;
  let exporting = false;
  let connected = false;
  const HANDLE_DB = 'KravenContentStudio';
  const HANDLE_STORE = 'handles';

  const $ = (s)=>document.querySelector(s);
  function toast(msg,type='info'){
    if(typeof window.showToast==='function') window.showToast(msg,type);
    else console.info('[Kraven Content]',msg);
  }
  function safeName(s){
    return String(s||'item').replace(/[^a-zA-Z0-9\u0600-\u06ff_-]+/g,'-').replace(/^-+|-+$/g,'').slice(0,80)||'item';
  }
  function extFromData(data){
    const m=String(data||'').match(/^data:image\/([a-zA-Z0-9.+-]+);base64,/);
    if(!m) return 'png';
    let e=m[1].toLowerCase(); if(e==='jpeg') e='jpg'; if(e==='svg+xml') e='svg';
    return e;
  }
  function dataToBytes(data){
    const i=String(data).indexOf(',');
    const bin=atob(String(data).slice(i+1));
    const bytes=new Uint8Array(bin.length);
    for(let j=0;j<bin.length;j++) bytes[j]=bin.charCodeAt(j);
    return bytes;
  }
  async function openMetaDB(){
    return new Promise((resolve,reject)=>{
      const r=indexedDB.open(HANDLE_DB,1);
      r.onupgradeneeded=()=>{ const d=r.result; if(!d.objectStoreNames.contains(HANDLE_STORE)) d.createObjectStore(HANDLE_STORE,{keyPath:'id'}); };
      r.onsuccess=()=>resolve(r.result); r.onerror=()=>reject(r.error);
    });
  }
  async function saveHandle(h){ try{const d=await openMetaDB(); const tx=d.transaction(HANDLE_STORE,'readwrite'); tx.objectStore(HANDLE_STORE).put({id:'project',handle:h}); await new Promise((res,rej)=>{tx.oncomplete=res;tx.onerror=()=>rej(tx.error)}); d.close();}catch(e){console.warn(e);} }
  async function loadHandle(){ try{const d=await openMetaDB(); const tx=d.transaction(HANDLE_STORE,'readonly'); const r=tx.objectStore(HANDLE_STORE).get('project'); const v=await new Promise((res,rej)=>{r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)}); d.close(); return v?.handle||null;}catch(e){return null;} }
  async function hasWritePermission(h){
    if(!h) return false;
    try{
      const q=await h.queryPermission({mode:'readwrite'});
      if(q==='granted') return true;
      const r=await h.requestPermission({mode:'readwrite'});
      return r==='granted';
    }catch(e){ return false; }
  }
  async function getDir(root, path, create=true){
    let h=root; for(const part of path.split('/').filter(Boolean)) h=await h.getDirectoryHandle(part,{create}); return h;
  }
  async function writeText(root,path,text){
    const parts=path.split('/'); const file=parts.pop(); const d=await getDir(root,parts.join('/')); const fh=await d.getFileHandle(file,{create:true}); const w=await fh.createWritable(); await w.write(text); await w.close();
  }
  async function writeBytes(root,path,bytes){
    const parts=path.split('/'); const file=parts.pop(); const d=await getDir(root,parts.join('/')); const fh=await d.getFileHandle(file,{create:true}); const w=await fh.createWritable(); await w.write(bytes); await w.close();
  }
  async function readJson(path){
    try{
      const r=await fetch(path,{cache:'no-store'});
      if(!r.ok) return null;
      return await r.json();
    }catch(e){ return null; }
  }
  function updateUI(){
    const wrap=$('#kraven-content-sync'); if(!wrap) return;
    const status=wrap.querySelector('[data-sync-status]');
    const txt=connected?(dirty?'● تغییرات در صف ذخیره':'✓ پوشه پروژه متصل است'):'○ پوشه پروژه متصل نیست';
    if(status) status.textContent=txt;
    const cls=connected?(dirty?'dirty':'ok'):'idle'; wrap.classList.toggle('is-dirty',cls==='dirty'); wrap.classList.toggle('is-connected',connected);
  }
  async function exportStore(store, records){
    const transformed=[];
    for(const original of records){
      const r=JSON.parse(JSON.stringify(original));
      const base=safeName(r.id||r.title||'item');
      async function externalize(obj, field, suffix){
        if(typeof obj?.[field]!=='string' || !obj[field].startsWith('data:image/')) return;
        const ext=extFromData(obj[field]);
        const rel=`${ASSET_ROOT}/${store}/${base}-${suffix}.${ext}`;
        await writeBytes(dirHandle,rel,dataToBytes(obj[field]));
        obj[field]=rel;
      }
      await externalize(r,'imageData','cover');
      await externalize(r,'mobileImageData','mobile');
      if(Array.isArray(r.gallery)){
        const g=[];
        for(let i=0;i<r.gallery.length;i++){
          if(typeof r.gallery[i]==='string' && r.gallery[i].startsWith('data:image/')){
            const ext=extFromData(r.gallery[i]); const rel=`${ASSET_ROOT}/${store}/${base}-gallery-${i+1}.${ext}`;
            await writeBytes(dirHandle,rel,dataToBytes(r.gallery[i])); g.push(rel);
          }else g.push(r.gallery[i]);
        }
        r.gallery=g;
      }
      transformed.push(r);
    }
    await writeText(dirHandle,`${ROOT}/${FILES[store]}`,JSON.stringify(transformed,null,2));
  }
  async function exportAll(){
    if(!connected||!dirHandle||exporting) return false;
    exporting=true; updateUI();
    try{
      const bridge=window.KRAVEN_CONTENT_BRIDGE; if(!bridge) throw new Error('bridge unavailable');
      for(const store of CONTENT_STORES){ const recs=await bridge.getAll(store); await exportStore(store,recs); }
      const meta={version:13,updatedAt:new Date().toISOString(),stores:CONTENT_STORES};
      await writeText(dirHandle,'data/content-manifest.json',JSON.stringify(meta,null,2));
      dirty=false; localStorage.setItem('kraven_content_files_active','1');
      updateUI(); toast('تغییرات محتوا در فایل‌های پروژه ذخیره شد','success'); return true;
    }catch(e){ console.error('[Kraven Content] export failed',e); toast('ذخیره فایل محتوا ناموفق بود: '+(e.message||'خطای ناشناخته'),'error'); return false; }
    finally{exporting=false; updateUI();}
  }
  function schedule(){ dirty=true; updateUI(); clearTimeout(timer); if(connected) timer=setTimeout(exportAll,AUTO_MS); }
  async function connectFolder(){
    if(!window.showDirectoryPicker){ toast('این مرورگر از اتصال مستقیم پوشه پشتیبانی نمی‌کند؛ Chrome یا Edge را امتحان کن','warning'); return; }
    try{
      const h=await window.showDirectoryPicker({mode:'readwrite'});
      if(!(await hasWritePermission(h))){toast('اجازه نوشتن در پوشه داده نشد','warning');return;}
      dirHandle=h; connected=true; await saveHandle(h); updateUI(); toast('پوشه پروژه متصل شد؛ Auto-Save هر ۱۰ ثانیه فعال است','success');
      if(dirty) schedule();
    }catch(e){ if(e?.name!=='AbortError') toast('اتصال پوشه ناموفق بود','error'); }
  }
  async function restoreConnection(){
    const h=await loadHandle(); if(!h) return;
    try{ const p=await h.queryPermission({mode:'readwrite'}); if(p==='granted'){dirHandle=h;connected=true;updateUI();} }catch(e){}
  }
  function downloadText(name,text){ const a=document.createElement('a'); a.href=URL.createObjectURL(new Blob([text],{type:'application/json'})); a.download=name; document.body.appendChild(a); a.click(); setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500); }
  async function fallbackDownload(){
    const bridge=window.KRAVEN_CONTENT_BRIDGE; if(!bridge) return;
    for(const store of CONTENT_STORES){ const recs=await bridge.getAll(store); downloadText(FILES[store],JSON.stringify(recs,null,2)); await new Promise(r=>setTimeout(r,120)); }
    toast('فایل‌های JSON دانلود شدند؛ آن‌ها را داخل پوشه data پروژه قرار بده','info');
  }
  async function loadPublished(){
    const results=await Promise.all(CONTENT_STORES.map(async store=>[store,await readJson(`${ROOT}/${FILES[store]}`)]));
    const available=results.filter(([,v])=>Array.isArray(v));
    if(!available.length) return false;
    const bridge=window.KRAVEN_CONTENT_BRIDGE; if(!bridge) return false;
    for(const [store,records] of available){
      await bridge.clear(store);
      for(const rec of records) await bridge.put(store,resolvePublishedPaths(rec));
    }
    window.__KRAVEN_CONTENT_FILES_LOADED=true;
    localStorage.setItem('kraven_content_files_active','1');
    console.info('[Kraven Content] published JSON loaded:',available.map(([s])=>s));
    return true;
  }
  function resolvePublishedPaths(v){
    const r=JSON.parse(JSON.stringify(v));
    for(const k of ['imageData','mobileImageData']) if(typeof r[k]==='string' && /^assets\//.test(r[k])) r[k]=new URL(r[k],document.baseURI).href;
    if(Array.isArray(r.gallery)) r.gallery=r.gallery.map(x=>typeof x==='string'&&/^assets\//.test(x)?new URL(x,document.baseURI).href:x);
    return r;
  }
  function injectUI(){
    if($('#kraven-content-sync')) return;
    const el=document.createElement('aside'); el.id='kraven-content-sync'; el.innerHTML=`<div class="kcs-title">📦 Kraven Content Engine</div><div class="kcs-status" data-sync-status>○ پوشه پروژه متصل نیست</div><div class="kcs-actions"><button type="button" class="kcs-btn" data-kcs-connect>اتصال پوشه پروژه</button><button type="button" class="kcs-btn" data-kcs-export>ذخیره همین حالا</button><button type="button" class="kcs-btn ghost" data-kcs-download>دانلود JSON</button></div><small>ذخیره خودکار ۱۰ ثانیه بعد از آخرین تغییر</small>`;
    document.body.appendChild(el);
    el.querySelector('[data-kcs-connect]').addEventListener('click',connectFolder);
    el.querySelector('[data-kcs-export]').addEventListener('click',exportAll);
    el.querySelector('[data-kcs-download]').addEventListener('click',fallbackDownload);
    const obs=new MutationObserver(()=>{el.classList.toggle('admin-visible',document.body.classList.contains('admin-mode'));}); obs.observe(document.body,{attributes:true,attributeFilter:['class']});
    el.classList.toggle('admin-visible',document.body.classList.contains('admin-mode'));
  }
  async function boot(){
    injectUI(); await restoreConnection();
    if(connected) updateUI();
  }
  window.KRAVEN_CONTENT_SYNC={schedule,connectFolder,exportAll,loadPublished,boot,isConnected:()=>connected};
  document.addEventListener('DOMContentLoaded',boot,{once:true});
})();


/* =========================================================
   KRAVEN V16 — cinematic home spotlight + micro interactions
   ========================================================= */
(function(){
'use strict';
const $=s=>document.querySelector(s);
const safe=(fn)=>{try{return fn()}catch(e){console.warn('Kraven V16:',e)}};
async function setupSpotlight(){
  const hero=$('#v16-hero'); if(!hero||hero.dataset.ready)return;
  hero.dataset.ready='1';
  try{
    let games=[];
    if(typeof getGames==='function') games=await getGames();
    if(!games.length){const r=await fetch('data/games.json');games=await r.json()}
    games=(games||[]).filter(Boolean);
    const rated=[...games].sort((a,b)=>(parseFloat(b.rating)||0)-(parseFloat(a.rating)||0));
    const game=rated[0]||games[0];
    if(!game)return;
    const img=game.imageData||game.mobileImageData||'';
    const bg=hero.querySelector('.v16-hero-bg'); if(bg&&img)bg.style.backgroundImage=`url("${String(img).replace(/"/g,'\\"')}")`;
    const title=$('#v16-hero-title'),desc=$('#v16-hero-desc'),score=$('#v16-score'),meta=$('#v16-hero-meta');
    if(title)title.textContent=game.title||'Kraven Spotlight';
    if(desc)desc.textContent=game.shortDesc||'یک انتخاب ویژه از آرشیو Kraven Game.';
    if(score)score.textContent=(parseFloat(game.rating)||0).toFixed(1);
    if(meta)meta.innerHTML=[game.genre,game.year,game.platform].filter(Boolean).slice(0,3).map(x=>`<span>${String(x)}</span>`).join('');
    const open=$('#v16-hero-open'); if(open)open.onclick=()=>window._navigateToGame&&window._navigateToGame(game.id);
    const random=$('#v16-hero-random'); if(random)random.onclick=()=>window._go&&window._go('home')||window._navigateToGame&&window._navigateToGame(games[Math.floor(Math.random()*games.length)].id);
    const total=$('#v16-games-total');if(total)total.textContent=games.length.toLocaleString('fa-IR');
    const genres=$('#v16-genres-total');if(genres)genres.textContent=new Set(games.map(g=>g.genre).filter(Boolean)).size.toLocaleString('fa-IR');
    const news=$('#v16-news-total');if(news){try{const n=typeof getNews==='function'?await getNews():(await fetch('data/news.json')).json();news.textContent=(Array.isArray(n)?n.length:0).toLocaleString('fa-IR')}catch(e){news.textContent='—'}}
  }catch(e){console.warn('V16 spotlight failed',e)}
}
function premiumCardMotion(){
  document.querySelectorAll('.game-card').forEach(card=>{
    if(card.dataset.v16Tilt)return;card.dataset.v16Tilt='1';
    card.addEventListener('pointermove',e=>{if(window.innerWidth<900)return;const r=card.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;card.style.transform=`translateY(-9px) perspective(900px) rotateX(${(-y*2.2).toFixed(2)}deg) rotateY(${(x*2.2).toFixed(2)}deg)`},{passive:true});
    card.addEventListener('pointerleave',()=>card.style.transform='');
  });
}
function observe(){const root=document.querySelector('main');if(!root||!window.MutationObserver)return;let t;new MutationObserver(()=>{clearTimeout(t);t=setTimeout(premiumCardMotion,100)}).observe(root,{subtree:true,childList:true});}
document.addEventListener('DOMContentLoaded',()=>{setTimeout(setupSpotlight,350);setTimeout(premiumCardMotion,900);observe()},{once:true});
window.addEventListener('kraven:navigate',()=>{setTimeout(setupSpotlight,250);setTimeout(premiumCardMotion,500)});
})();
